insert into public.animacoes (id, dados) values ('ipc-blackfriday', $animasys${"atualizadoEm":1790618520000,"baseCss":"/* estrutura de teste (imita a loja) */\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: Arial, Helvetica, sans-serif; background: #f2f2f2; color: #222; }\n#header-main { position: relative; }\n#header-main .header-1 { background: #111; color: #cfcfcf; font-size: 12px; padding: 10px 24px; display: flex; gap: 22px; }\n#header-main .header-2 { background: #ffd200; display: flex; align-items: center; gap: 28px; padding: 26px 24px; }\n.logo { width: 205px; flex: none; } .logo img { display: block; width: 205px; height: auto; }\n.element-search { flex: 1; } .search-field { width: 100%; height: 42px; border: 0; border-radius: 4px; padding: 0 14px; font-size: 14px; }\n.user-info, .link-shopping-cart { display: flex; align-items: center; gap: 8px; font-size: 12px; line-height: 1.35; position: relative; }\n.icon-user, .icon-shopping-cart { display: inline-block; width: 30px; height: 30px; background: center / contain no-repeat; }\n.icon-user { background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%3E%3Ccircle%20cx%3D%2216%22%20cy%3D%2211%22%20r%3D%226%22%20fill%3D%22%23111%22%2F%3E%3Cpath%20d%3D%22M5%2029c1-7%206-10%2011-10s10%203%2011%2010z%22%20fill%3D%22%23111%22%2F%3E%3C%2Fsvg%3E\"); }\n.icon-shopping-cart { background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%3E%3Cpath%20d%3D%22M6%2011h20l-2%2018H8z%22%20fill%3D%22%23111%22%2F%3E%3Cpath%20d%3D%22M11%2012V9a5%205%200%200%201%2010%200v3%22%20fill%3D%22none%22%20stroke%3D%22%23111%22%20stroke-width%3D%222.4%22%2F%3E%3C%2Fsvg%3E\"); }\n#nav-main { background: #fff; display: flex; gap: 28px; padding: 13px 24px; font-size: 14px; font-weight: bold; border-bottom: 1px solid #e3e3e3; }\n.vitrine { list-style: none; margin: 0; padding: 22px 24px; display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 16px; }\n.product-list-item-inner { position: relative; background: #fff; border-radius: 6px; padding: 16px; text-align: center; }\n.label-promo { position: absolute; top: 10px; left: 10px; background: #e30613; color: #fff; font-size: 11px; font-weight: bold; padding: 3px 6px; border-radius: 3px; }\n.product-image img { width: 120px; height: 120px; }\n.product-name { font-size: 13px; margin: 8px 0; }\n.ipc-card-price { font-weight: bold; font-size: 16px; margin-bottom: 10px; }\n.btn-buy-kit { display: inline-block; background: #111; color: #fff; border: 1px solid #111; border-radius: 4px; padding: 8px 20px; text-decoration: none; font-size: 13px; font-weight: bold; }\n.wa-chat-wrapper { position: fixed; right: 24px; bottom: 24px; z-index: 10; }\n.wa-chat-header { background: #57bb63; border-radius: 999px; }\n.wa-chat-header a { color: #fff; font-weight: bold; font-size: 14px; }\n.wa-chat-icon { display: inline-block; width: 30px; height: 30px; background: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%3E%3Cpath%20d%3D%22M16%204C9%204%204%209%204%2015c0%202.4.8%204.6%202.2%206.4L5%2028l6.8-1.9c1.3.6%202.7.9%204.2.9%207%200%2012-5%2012-12S23%204%2016%204z%22%20fill%3D%22%23fff%22%2F%3E%3Cpath%20d%3D%22M11.5%2011.5c.4-.9%201.3-.8%201.6-.1l.9%202c.2.4%200%20.8-.3%201.1l-.6.6c.8%201.6%202.1%202.9%203.8%203.7l.6-.6c.3-.3.7-.4%201.1-.2l2%20.9c.7.3.8%201.2-.1%201.6-2.6%201.4-9.9-4.6-9-9z%22%20fill%3D%22%2357bb63%22%2F%3E%3C%2Fsvg%3E\") center / contain no-repeat; }\n#banner-shop { list-style: none; margin: 0; padding: 26px 24px 4px; display: flex; flex-wrap: wrap; justify-content: center; gap: 22px; background: #fff; }\n#banner-shop .banner-item img { width: 130px; height: 130px; display: block; }\n@media (max-width: 700px) { .element-search, .user-txt, .cart-txt { display: none; } }","baseHtml":"<div id=\"header-main\">\n  <div class=\"header-1\"><span>(21) 2038-9971</span><span>(11) 3136-1560 (WhatsApp)</span><span>Seg a Sex · 08h às 17h</span></div>\n  <div class=\"header-2\">\n    <div class=\"element-logo\"><div class=\"logo\"><!--ANIMACAO--></div></div>\n    <div class=\"element-search\"><input class=\"search-field\" placeholder=\"O que você procura?\" aria-label=\"Buscar\"></div>\n    <div class=\"user-info\"><span class=\"icon-user\"></span><span class=\"user-txt\">Bem-vindo!<br>Entre ou cadastre-se</span></div>\n    <div class=\"link-shopping-cart\"><span class=\"icon-shopping-cart\"></span><span class=\"cart-txt\">Itens <span class=\"shopping-cart-total-products\">0</span><br><span class=\"shopping-cart-total-price\">R$ 0,00</span></span></div>\n  </div>\n  <nav id=\"nav-main\"><a>Rodízios</a><a>Roletes</a><a>Esferas</a><a>Rodas</a><a>Acessórios</a></nav>\n</div>\n\n<ul class=\"vitrine\">\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-10%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio giratório 50 mm\"></div>\n      <div class=\"product-name\">Rodízio giratório 50 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 18,90</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio fixo com freio\"></div>\n      <div class=\"product-name\">Rodízio fixo com freio</div>\n      <div class=\"ipc-card-price\"><span>R$ 24,50</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-15%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Roda de gel 75 mm\"></div>\n      <div class=\"product-name\">Roda de gel 75 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 31,00</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n","criadoEm":1790618520000,"css":"/* ---------- 4. Logo: bolinha desce a escada e volta com um super impulso ---------- */\n/* Medidas em % da imagem original (205x90): bolinha em x50 y2, 16px.\n   Nos translate, 100% = diâmetro da bolinha. Degraus: barra 2 (topo y43),\n   barra 1 (topo y66), chão (y88). Roda uma vez por carregamento.\n   A altura dos pulos vem de --ipc-ball-apex / --ipc-ball-hop, calculadas no JS\n   para a bolinha nunca sair da faixa amarela (sem JS: pulo baixo). */\n.logo a.ipc-logo-anim {\n  position: relative;\n}\n.ipc-logo-ball {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  background: #15161a;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n  animation: ipc-ball-escada 2.6s .6s 1 both;\n}\n@keyframes ipc-ball-escada {\n  0%   { transform: translate(0, 0) scale(1);               animation-timing-function: ease-out; }\n  5%   { transform: translate(0, 0) scale(1.18, .82);        animation-timing-function: ease-out; }\n  12%  { transform: translate(-60%, var(--ipc-ball-hop, -10%)) scale(.95, 1.05);  animation-timing-function: ease-in; }\n  21%  { transform: translate(-109%, 156%) scale(1);          animation-timing-function: ease-out; }\n  23%  { transform: translate(-109%, 156%) scale(1.25, .75); animation-timing-function: ease-out; }\n  31%  { transform: translate(-165%, 95%) scale(1);          animation-timing-function: ease-in; }\n  40%  { transform: translate(-216%, 300%) scale(1);          animation-timing-function: ease-out; }\n  42%  { transform: translate(-216%, 300%) scale(1.25, .75); animation-timing-function: ease-out; }\n  50%  { transform: translate(-268%, 235%) scale(1);          animation-timing-function: ease-in; }\n  59%  { transform: translate(-312%, 437%) scale(1);          animation-timing-function: ease-out; }\n  62%  { transform: translate(-312%, 437%) scale(1.3, .7);    animation-timing-function: ease-in-out; }\n  /* carregando o impulso */\n  70%  { transform: translate(-312%, 437%) scale(1.55, .45); animation-timing-function: cubic-bezier(.15, .9, .3, 1); }\n  /* super impulso: estica na subida */\n  76%  { transform: translate(-230%, 60%) scale(.72, 1.45);  animation-timing-function: ease-out; }\n  84%  { transform: translate(-90%, var(--ipc-ball-apex, -10%)) scale(.95, 1.08); animation-timing-function: ease-in; }\n  93%  { transform: translate(0, 0) scale(1.3, .72);          animation-timing-function: ease-out; }\n  97%  { transform: translate(0, calc(var(--ipc-ball-hop, -10%) * .4)) scale(.94, 1.06);      animation-timing-function: ease-in; }\n  100% { transform: translate(0, 0) scale(1); }\n}\n@media (prefers-reduced-motion: reduce) { .ipc-logo-ball { animation: none; } }\n\n/* ===== blackfriday ===== */\n/* Tema de Black Friday — IPC Comercial (cópia local)\n * Ativado pela classe body.ipc-bf (colocada pelo blackfriday.js).\n * Para desligar: ATIVO = false no blackfriday.js (ou remova as duas linhas no index.html). */\n\n/* ---------- 1. Explosão preta e vermelha quando a bolinha do logo volta ---------- */\n.ipc-bf-burst {\n  position: absolute;\n  z-index: 60;\n  overflow: hidden;\n  pointer-events: none;\n}\n.ipc-bf-p {\n  position: absolute;\n  font: 800 12px/1 Poppins, sans-serif;\n  opacity: 0;\n  animation: ipc-bf-confete 1.1s cubic-bezier(.15, .7, .35, 1) var(--d, 0s) 1 both;\n}\n/* Onda de choque vermelha no centro da explosão. */\n.ipc-bf-onda {\n  position: absolute;\n  width: 40px;\n  height: 40px;\n  margin: -20px 0 0 -20px;\n  border: 3px solid #e03131;\n  border-radius: 50%;\n  pointer-events: none;\n  animation: ipc-bf-onda .7s ease-out 0s 1 both;\n}\n@keyframes ipc-bf-onda {\n  0%   { transform: scale(.2); opacity: 0; }\n  10%  { opacity: 1; }\n  100% { transform: scale(4); opacity: 0; border-width: 1px; }\n}\n.ipc-bf-p.fita {\n  width: 7px;\n  height: 3px;\n  border-radius: 1px;\n}\n@keyframes ipc-bf-confete {\n  0%   { transform: translate(-50%, -50%) scale(.2) rotate(0); opacity: 1; }\n  55%  { transform: translate(calc(-50% + var(--dx)), calc(-50% + var(--dy))) scale(1) rotate(var(--rot)); opacity: 1; }\n  100% { transform: translate(calc(-50% + var(--dx) * 1.15), calc(-50% + var(--dy) + 22px)) scale(.9) rotate(calc(var(--rot) * 1.6)); opacity: 0; }\n}\n\n/* ---------- 2. Etiquetas de desconto no estilo Black Friday ---------- */\nbody.ipc-bf .label-promo {\n  background: #0b0b0d !important;\n  color: #ffd700 !important;\n  border: 1px solid #ffd700;\n  transform-origin: 50% -6px;\n  animation: ipc-bf-etiqueta 1.3s ease-out var(--d, .8s) 1 both;\n}\nbody.ipc-bf .ipc-bf-off {\n  background: #0b0b0d !important;\n  color: #ffd700 !important;\n  display: inline-block;\n  transform-origin: 0 50%;\n  animation: ipc-bf-selo .6s cubic-bezier(.34, 1.56, .64, 1) var(--d, .8s) 1 both;\n}\n@keyframes ipc-bf-etiqueta {\n  0%   { transform: rotate(-28deg); opacity: 0; }\n  15%  { opacity: 1; }\n  35%  { transform: rotate(16deg); }\n  55%  { transform: rotate(-9deg); }\n  75%  { transform: rotate(4deg); }\n  100% { transform: rotate(0); opacity: 1; }\n}\n@keyframes ipc-bf-selo {\n  from { transform: scale(.3); opacity: 0; }\n  to   { transform: scale(1); opacity: 1; }\n}\n\n/* ---------- 3. Brilho passando nos botões \"Comprar\" ---------- */\nbody.ipc-bf .btn-buy-kit {\n  position: relative;\n  overflow: hidden;\n}\nbody.ipc-bf .btn-buy-kit::after {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: -60%;\n  width: 45%;\n  background: linear-gradient(100deg, transparent, rgba(255, 255, 255, .55), transparent);\n  transform: skewX(-20deg);\n  pointer-events: none;\n  animation: ipc-bf-reflexo .9s ease-in-out var(--d, 1.4s) 1 both;\n}\n@keyframes ipc-bf-reflexo {\n  from { left: -60%; }\n  to   { left: 130%; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  body.ipc-bf .label-promo, body.ipc-bf .ipc-bf-off,\n  body.ipc-bf .btn-buy-kit::after { animation: none; }\n  .ipc-bf-burst { display: none; }\n}\n","descricao":"Explosão preta e vermelha de \"%\" no logo, etiquetas \"% OFF\" pretas nos produtos e brilho nos botões de comprar. Precisa da bolinha do logo (já inclusa aqui).","html":"<a href=\"/\" class=\"ipc-logo-anim\"><img src=\"data:image/png;base64,\" alt=\"IPC Comercial\" title=\"IPC Comercial\"><span class=\"ipc-logo-ball\" aria-hidden=\"true\"></span></a>","js":"/* Bolinha do logo: limita a altura dos pulos ao espaço amarelo acima dela */\n(function fitLogoBall() {\n  var ball = document.querySelector('.ipc-logo-ball');\n  if (!ball) return;\n  var blackBar = document.querySelector('#header-main .header-1');\n  var r = ball.getBoundingClientRect();\n  var d = r.width;\n  if (!d) return;\n  var limit = blackBar ? blackBar.getBoundingClientRect().bottom : r.top - d;\n  var margin = 4;\n  // No ápice a bolinha estica 8% para cima (scale 1.08 com origem embaixo).\n  var room = r.top - limit - margin - d * 0.08;\n  var apex = Math.max(-330, Math.min(0, -room / d * 100));\n  var hop = Math.max(apex, -70);\n  ball.style.setProperty('--ipc-ball-apex', apex.toFixed(1) + '%');\n  ball.style.setProperty('--ipc-ball-hop', hop.toFixed(1) + '%');\n})();\n\n/* ===== blackfriday ===== */\n/* Tema de Black Friday — IPC Comercial (cópia local)\n * - explosão preta e vermelha de \"%\" quando a bolinha do logo volta do super impulso\n * - etiquetas \"% OFF\" pretas e amarelas, entrando com balanço\n * - reflexo de luz passando nos botões \"Comprar\"\n * As animações rodam uma vez por carregamento.\n * Para desligar: ATIVO = false. */\n(function () {\n  var ATIVO = true;\n  // ?tema=... na URL escolhe o tema (para comparar os temas em abas separadas).\n  var temaUrl = new URLSearchParams(location.search).get('tema');\n  if (temaUrl) ATIVO = temaUrl === 'blackfriday';\n\n  if (!ATIVO) return;\n  document.body.classList.add('ipc-bf');\n  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function box(el) {\n    var r = el.getBoundingClientRect();\n    return { left: r.left + window.scrollX, top: r.top + window.scrollY, width: r.width, bottom: r.bottom + window.scrollY };\n  }\n\n  // Estoura confetes (\"%\" e fitinhas) a partir de (cx, cy) dentro de `container`\n  // (que precisa ter position e overflow: hidden para recortar os pedaços).\n  function explodir(container, cx, cy, o) {\n    var onda = document.createElement('span');\n    onda.className = 'ipc-bf-onda';\n    onda.style.left = cx + 'px';\n    onda.style.top = cy + 'px';\n    onda.style.animationDelay = o.delay + 's';\n    container.appendChild(onda);\n    var pecas = [onda];\n\n    for (var i = 0; i < o.qtd; i++) {\n      var p = document.createElement('span');\n      var fita = i % 3 === 2;\n      var cor = o.cores[i % o.cores.length];\n      p.className = 'ipc-bf-p' + (fita ? ' fita' : '');\n      if (fita) p.style.background = cor;\n      else { p.textContent = '%'; p.style.color = cor; p.style.fontSize = 10 + Math.round(Math.random() * 6) + 'px'; }\n      var ang = (i / o.qtd) * Math.PI * 2 + Math.random() * 0.35;\n      var dist = o.dist * (0.55 + Math.random() * 0.6);\n      p.style.left = cx + 'px';\n      p.style.top = cy + 'px';\n      p.style.setProperty('--dx', Math.cos(ang) * dist * o.sx + 'px');\n      p.style.setProperty('--dy', Math.sin(ang) * dist * o.sy + 'px');\n      p.style.setProperty('--rot', (Math.random() * 360 - 180) + 'deg');\n      p.style.setProperty('--d', o.delay + Math.random() * 0.08 + 's');\n      container.appendChild(p);\n      pecas.push(p);\n    }\n    setTimeout(function () {\n      pecas.forEach(function (p) { p.remove(); });\n    }, (o.delay + 1.4) * 1000);\n  }\n\n  /* ---------- 1. Explosão de \"%\" no logo ---------- */\n  (function explosao() {\n    var ball = document.querySelector('.ipc-logo-ball');\n    if (!ball || reduceMotion) return;\n\n    ball.addEventListener('animationend', function (e) {\n      if (e.animationName !== 'ipc-ball-escada') return;\n      var header = document.querySelector('#header-main');\n      var black = document.querySelector('#header-main .header-1');\n      if (!header) return;\n\n      // Camada recortada na faixa amarela: os confetes nunca entram no preto.\n      var hb = box(header);\n      var top = black ? box(black).bottom : hb.top;\n      var layer = document.createElement('div');\n      layer.className = 'ipc-bf-burst';\n      layer.style.left = hb.left + 'px';\n      layer.style.top = top + 'px';\n      layer.style.width = hb.width + 'px';\n      layer.style.height = hb.bottom - top + 'px';\n\n      var b = box(ball);\n      document.body.appendChild(layer);\n      explodir(layer, b.left + b.width / 2 - hb.left, (b.top + b.bottom) / 2 - top, {\n        qtd: 30, dist: 70, sx: 1.8, sy: 0.75, delay: 0, cores: ['#0b0b0d', '#e03131']\n      });\n      setTimeout(function () { layer.remove(); }, 1600);\n    });\n  })();\n\n  /* ---------- 2. Etiquetas \"% OFF\" ---------- */\n  // O selo verde perto do preço é injetado pelo script da loja depois do carregamento,\n  // então observa a página por alguns segundos e estiliza o que for aparecendo.\n  (function etiquetas() {\n    var n = 0;\n    function marcar() {\n      document.querySelectorAll('.label-promo:not(.ipc-bf-lbl)').forEach(function (el) {\n        el.classList.add('ipc-bf-lbl');\n        el.style.setProperty('--d', (0.8 + (n++ % 4) * 0.15) + 's');\n      });\n      document.querySelectorAll('.ipc-card-price span:not(.ipc-bf-off)').forEach(function (el) {\n        if (el.children.length || !/%\\s*OFF/i.test(el.textContent)) return;\n        el.classList.add('ipc-bf-off');\n        el.style.setProperty('--d', (1 + (n++ % 4) * 0.12) + 's');\n      });\n    }\n    marcar();\n    var mo = new MutationObserver(marcar);\n    mo.observe(document.body, { childList: true, subtree: true });\n    setTimeout(function () { mo.disconnect(); }, 8000);\n  })();\n\n  /* ---------- 3. Reflexo nos botões \"Comprar\" (em onda, por coluna) ---------- */\n  document.querySelectorAll('.btn-buy-kit').forEach(function (btn, i) {\n    btn.style.setProperty('--d', (1.4 + (i % 4) * 0.15) + 's');\n  });\n})();\n","noAr":true,"ordem":3,"pagina":"site-ipc/index.html#blackfriday","secao":"Datas comemorativas","secaoOrdem":2,"sistema":"IPC Comercial","tags":["novembro","preços"],"titulo":"Black Friday: explosão de % e etiquetas OFF"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
insert into public.animacoes (id, dados) values ('ipc-bolinha', $animasys${"atualizadoEm":1790618400000,"baseCss":"/* estrutura de teste (imita a loja) */\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: Arial, Helvetica, sans-serif; background: #f2f2f2; color: #222; }\n#header-main { position: relative; }\n#header-main .header-1 { background: #111; color: #cfcfcf; font-size: 12px; padding: 10px 24px; display: flex; gap: 22px; }\n#header-main .header-2 { background: #ffd200; display: flex; align-items: center; gap: 28px; padding: 26px 24px; }\n.logo { width: 205px; flex: none; } .logo img { display: block; width: 205px; height: auto; }\n.element-search { flex: 1; } .search-field { width: 100%; height: 42px; border: 0; border-radius: 4px; padding: 0 14px; font-size: 14px; }\n.user-info, .link-shopping-cart { display: flex; align-items: center; gap: 8px; font-size: 12px; line-height: 1.35; position: relative; }\n.icon-user, .icon-shopping-cart { display: inline-block; width: 30px; height: 30px; background: center / contain no-repeat; }\n.icon-user { background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%3E%3Ccircle%20cx%3D%2216%22%20cy%3D%2211%22%20r%3D%226%22%20fill%3D%22%23111%22%2F%3E%3Cpath%20d%3D%22M5%2029c1-7%206-10%2011-10s10%203%2011%2010z%22%20fill%3D%22%23111%22%2F%3E%3C%2Fsvg%3E\"); }\n.icon-shopping-cart { background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%3E%3Cpath%20d%3D%22M6%2011h20l-2%2018H8z%22%20fill%3D%22%23111%22%2F%3E%3Cpath%20d%3D%22M11%2012V9a5%205%200%200%201%2010%200v3%22%20fill%3D%22none%22%20stroke%3D%22%23111%22%20stroke-width%3D%222.4%22%2F%3E%3C%2Fsvg%3E\"); }\n#nav-main { background: #fff; display: flex; gap: 28px; padding: 13px 24px; font-size: 14px; font-weight: bold; border-bottom: 1px solid #e3e3e3; }\n.vitrine { list-style: none; margin: 0; padding: 22px