m\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio fixo com freio\"></div>\n      <div class=\"product-name\">Rodízio fixo com freio</div>\n      <div class=\"ipc-card-price\"><span>R$ 24,50</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-15%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Roda de gel 75 mm\"></div>\n      <div class=\"product-name\">Roda de gel 75 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 31,00</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n","criadoEm":1790618580000,"css":"/* ---------- 4. Logo: bolinha desce a escada e volta com um super impulso ---------- */\n/* Medidas em % da imagem original (205x90): bolinha em x50 y2, 16px.\n   Nos translate, 100% = diâmetro da bolinha. Degraus: barra 2 (topo y43),\n   barra 1 (topo y66), chão (y88). Roda uma vez por carregamento.\n   A altura dos pulos vem de --ipc-ball-apex / --ipc-ball-hop, calculadas no JS\n   para a bolinha nunca sair da faixa amarela (sem JS: pulo baixo). */\n.logo a.ipc-logo-anim {\n  position: relative;\n}\n.ipc-logo-ball {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  background: #15161a;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n  animation: ipc-ball-escada 2.6s .6s 1 both;\n}\n@keyframes ipc-ball-escada {\n  0%   { transform: translate(0, 0) scale(1);               animation-timing-function: ease-out; }\n  5%   { transform: translate(0, 0) scale(1.18, .82);        animation-timing-function: ease-out; }\n  12%  { transform: translate(-60%, var(--ipc-ball-hop, -10%)) scale(.95, 1.05);  animation-timing-function: ease-in; }\n  21%  { transform: translate(-109%, 156%) scale(1);          animation-timing-function: ease-out; }\n  23%  { transform: translate(-109%, 156%) scale(1.25, .75); animation-timing-function: ease-out; }\n  31%  { transform: translate(-165%, 95%) scale(1);          animation-timing-function: ease-in; }\n  40%  { transform: translate(-216%, 300%) scale(1);          animation-timing-function: ease-out; }\n  42%  { transform: translate(-216%, 300%) scale(1.25, .75); animation-timing-function: ease-out; }\n  50%  { transform: translate(-268%, 235%) scale(1);          animation-timing-function: ease-in; }\n  59%  { transform: translate(-312%, 437%) scale(1);          animation-timing-function: ease-out; }\n  62%  { transform: translate(-312%, 437%) scale(1.3, .7);    animation-timing-function: ease-in-out; }\n  /* carregando o impulso */\n  70%  { transform: translate(-312%, 437%) scale(1.55, .45); animation-timing-function: cubic-bezier(.15, .9, .3, 1); }\n  /* super impulso: estica na subida */\n  76%  { transform: translate(-230%, 60%) scale(.72, 1.45);  animation-timing-function: ease-out; }\n  84%  { transform: translate(-90%, var(--ipc-ball-apex, -10%)) scale(.95, 1.08); animation-timing-function: ease-in; }\n  93%  { transform: translate(0, 0) scale(1.3, .72);          animation-timing-function: ease-out; }\n  97%  { transform: translate(0, calc(var(--ipc-ball-hop, -10%) * .4)) scale(.94, 1.06);      animation-timing-function: ease-in; }\n  100% { transform: translate(0, 0) scale(1); }\n}\n@media (prefers-reduced-motion: reduce) { .ipc-logo-ball { animation: none; } }\n\n/* ===== natal ===== */\n/* Tema de Natal — IPC Comercial (cópia local)\n * Ativado pela classe body.ipc-natal (colocada pelo natal.js).\n * Para desligar: ATIVO = false no natal.js (ou remova as duas linhas no index.html). */\n\n/* A bolinha do \"i\" some: quem vira o pingo é o presente que o Papai Noel solta. */\nbody.ipc-natal .ipc-logo-ball {\n  visibility: hidden;\n  animation: none;\n}\n\n/* ---------- Neve no cabeçalho, atrás de todo o conteúdo ---------- */\n/* O cabeçalho pinta o próprio fundo (preto em cima, amarelo embaixo) e a neve\n   fica numa camada com z-index -1: acima do fundo e abaixo de logo, busca e menus.\n   z-index 50 mantém o carrinho suspenso por cima do menu, como antes. */\n#header-main.ipc-natal-hdr {\n  position: relative;\n  z-index: 50;\n  background: linear-gradient(to bottom,\n    var(--ipc-preto) 0, var(--ipc-preto) var(--ipc-h1, 0px),\n    var(--ipc-amarelo) var(--ipc-h1, 0px)) !important;\n}\n#header-main .header-1.ipc-natal-transp {\n  background: transparent !important;\n}\n.ipc-natal-neve {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  z-index: -1;\n  pointer-events: none;\n}\n\n/* ---------- Gorro de Papai Noel no bonequinho de login ---------- */\n/* O bonequinho preto original continua visível; o gorro fica por cima,\n   na mesma caixa do ícone. */\n.ipc-natal-user {\n  position: absolute;\n  overflow: visible;\n  pointer-events: none;\n}\n/* Pontos de giro/escala das peças da roupa (as animações de vestir estão no JS). */\n.ipc-natal-user .roupa-casaco {\n  transform-box: fill-box;\n  transform-origin: 50% 100%;\n}\n.ipc-natal-user .fivela {\n  transform-box: fill-box;\n  transform-origin: 50% 50%;\n}\n.ipc-natal-user .roupa-rosto {\n  transform-box: fill-box;\n  transform-origin: 50% 25%;\n}\n.ipc-natal-user .gorro {\n  transform-box: fill-box;\n  transform-origin: 40% 100%;\n}\n.ipc-natal-user .pompom {\n  transform-box: view-box;\n  transform-origin: 19.6px -1.4px;\n}\n\n/* ---------- Presente (mesma caixa da bolinha do logo) ---------- */\n.ipc-natal-presente {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n}\n.ipc-natal-presente svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n\n/* ---------- Céu: faixa amarela recortada (nada entra na parte preta) ---------- */\n.ipc-natal-ceu {\n  position: absolute;\n  z-index: 60;\n  overflow: hidden;\n  pointer-events: none;\n}\n.ipc-natal-treno {\n  position: absolute;\n  left: 0;\n  top: 0;\n  transform-origin: 0 0;\n}\n.ipc-natal-treno svg {\n  display: block;\n  width: 100%;\n  height: auto;\n  overflow: visible;\n}\n\n/* Renas galopando */\n.ipc-natal-treno .pernas-frente,\n.ipc-natal-treno .pernas-tras {\n  transform-box: fill-box;\n  transform-origin: 50% 0;\n  animation: ipc-natal-galope .3s ease-in-out infinite alternate;\n}\n.ipc-natal-treno .pernas-tras { animation-direction: alternate-reverse; }\n.ipc-natal-treno .rena-bob {\n  animation: ipc-natal-bob .3s ease-in-out infinite alternate;\n}\n.ipc-natal-treno .rena-2 .rena-bob { animation-delay: -.15s; }\n.ipc-natal-treno .rena-2 .pernas-frente,\n.ipc-natal-treno .rena-2 .pernas-tras { animation-delay: -.15s; }\n\n/* Balanço dos sininhos */\n.ipc-natal-treno .sino {\n  transform-box: fill-box;\n  transform-origin: 50% 0;\n  animation: ipc-natal-sino .22s ease-in-out infinite alternate;\n}\n.ipc-natal-treno .sino-2 { animation-delay: -.11s; }\n@keyframes ipc-natal-sino {\n  from { transform: rotate(-25deg); }\n  to   { transform: rotate(25deg); }\n}\n\n/* Ao soltar o presente: o saco chacoalha e o Papai Noel acena */\n.ipc-natal-treno .saco {\n  transform-box: fill-box;\n  transform-origin: 50% 100%;\n}\n.ipc-natal-treno.soltou .saco {\n  animation: ipc-natal-saco .45s ease-out 1;\n}\n@keyframes ipc-natal-saco {\n  0%   { transform: scale(1); }\n  30%  { transform: scale(1.18, .82); }\n  60%  { transform: scale(.94, 1.08) rotate(-6deg); }\n  100% { transform: scale(1) rotate(0); }\n}\n.ipc-natal-treno .braco-aceno {\n  opacity: 0;\n  transform-box: view-box;\n  transform-origin: 29.5px 15.5px;\n}\n.ipc-natal-treno.soltou .braco-aceno {\n  opacity: 1;\n  animation: ipc-natal-aceno .32s ease-in-out .15s 6 alternate both;\n}\n@keyframes ipc-natal-aceno {\n  from { transform: rotate(-22deg); }\n  to   { transform: rotate(22deg); }\n}\n\n@keyframes ipc-natal-galope {\n  from { transform: rotate(30deg); }\n  to   { transform: rotate(-24deg); }\n}\n@keyframes ipc-natal-bob {\n  from { transform: translateY(-1.2px); }\n  to   { transform: translateY(1.2px); }\n}\n\n/* Rastro de brilhos atrás do trenó */\n.ipc-natal-brilho {\n  position: absolute;\n  margin: -5px 0 0 -5px;\n  font-size: 10px;\n  line-height: 1;\n  color: #fff;\n  text-shadow: 0 0 2px rgba(0, 0, 0, .35), 0 0 4px rgba(255, 255, 255, .9);\n  animation: ipc-natal-brilho .9s ease-out 1 both;\n}\n@keyframes ipc-natal-brilho {\n  0%   { transform: translate(0, 0) scale(.4) rotate(0); opacity: 0; }\n  20%  { transform: translate(calc(var(--dx) * .2), calc(var(--dy) * .2)) scale(1) rotate(40deg); opacity: 1; }\n  100% { transform: translate(var(--dx), var(--dy)) scale(.2) rotate(120deg); opacity: 0; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ipc-natal-ceu { display: none; }}\n","descricao":"Papai Noel passa de trenó e solta um presente que vira o pingo do \"i\"; neve contínua na faixa amarela e gorro no ícone do usuário. Precisa da bolinha do logo (já inclusa aqui).","html":"<a href=\"/\" class=\"ipc-logo-anim\"><img src=\"data:image/png;base64,\" alt=\"IPC Comercial\" title=\"IPC Comercial\"><span class=\"ipc-logo-ball\" aria-hidden=\"true\"></span></a>","js":"/* Bolinha do logo: limita a altura dos pulos ao espaço amarelo acima dela */\n(function fitLogoBall() {\n  var ball = document.querySelector('.ipc-logo-ball');\n  if (!ball) return;\n  var blackBar = document.querySelector('#header-main .header-1');\n  var r = ball.getBoundingClientRect();\n  var d = r.width;\n  if (!d) return;\n  var limit = blackBar ? blackBar.getBoundingClientRect().bottom : r.top - d;\n  var margin = 4;\n  // No ápice a bolinha estica 8% para cima (scale 1.08 com origem embaixo).\n  var room = r.top - limit - margin - d * 0.08;\n  var apex = Math.max(-330, Math.min(0, -room / d * 100));\n  var hop = Math.max(apex, -70);\n  ball.style.setProperty('--ipc-ball-apex', apex.toFixed(1) + '%');\n  ball.style.setProperty('--ipc-ball-hop', hop.toFixed(1) + '%');\n})();\n\n/* ===== natal ===== */\n/* Tema de Natal — IPC Comercial (cópia local)\n * - neve caindo no cabeçalho inteiro (parte preta e amarela), atrás do conteúdo\n *   e sem bloquear cliques; pausa quando o cabeçalho sai da tela\n * - o Papai Noel entra voando pelo canto esquerdo da faixa amarela, desacelera\n *   sobre o logo, solta um presente que cai no lugar do pingo do \"i\", acena e\n *   vai embora pela direita. O presente fica como pingo do \"i\".\n * O voo roda uma vez por carregamento. Para desligar: ATIVO = false. */\n(function () {\n  var ATIVO = true;\n  // ?tema=... na URL escolhe o tema (para comparar os temas em abas separadas).\n  var temaUrl = new URLSearchParams(location.search).get('tema');\n  if (temaUrl) ATIVO = temaUrl === 'natal';\n  if (!ATIVO) return;\n\n  var ball = document.querySelector('.ipc-logo-ball');\n  var header = document.querySelector('#header-main');\n  if (!ball || !header) return;\n  document.body.classList.add('ipc-natal');\n\n  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var black = document.querySelector('#header-main .header-1');\n\n  var PRESENTE_SVG =\n    '<svg viewBox=\"0 0 16 16\" aria-hidden=\"true\">' +\n      '<path d=\"M8 4.3C6 .5 2.6 1.6 4.2 3.6c.8.9 2.4.8 3.8.7zM8 4.3c2-3.8 5.4-2.7 3.8-.7-.8.9-2.4.8-3.8.7z\" fill=\"#2b8a3e\" stroke=\"#1b5e2a\" stroke-width=\".4\"/>' +\n      '<rect x=\"1.5\" y=\"6.4\" width=\"13\" height=\"9.6\" rx=\"1\" fill=\"#c92a2a\" stroke=\"#7a1414\" stroke-width=\".5\"/>' +\n      '<rect x=\".8\" y=\"4.3\" width=\"14.4\" height=\"3.2\" rx=\".8\" fill=\"#e03131\" stroke=\"#7a1414\" stroke-width=\".5\"/>' +\n      '<rect x=\"7\" y=\"4.3\" width=\"2\" height=\"11.7\" fill=\"#2b8a3e\"/>' +\n      '<path d=\"M2.6 8.2v5\" stroke=\"#fff\" stroke-opacity=\".35\" stroke-width=\".8\" stroke-linecap=\"round\"/>' +\n    '</svg>';\n\n  // Rena com o centro do corpo em (0,0), virada para a direita.\n  var RENA =\n    '<g class=\"rena-bob\">' +\n      '<g class=\"pernas-tras\"><path d=\"M-7 3l-2 9M-4 3l1 9\" stroke=\"#5c3a1a\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></g>' +\n      '<g class=\"pernas-frente\"><path d=\"M5 3l3 9M8 2l3 9\" stroke=\"#5c3a1a\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></g>' +\n      '<path d=\"M-11-2l-3-2.5\" stroke=\"#8d5a2b\" stroke-width=\"2\" stroke-linecap=\"round\"/>' +\n      '<ellipse rx=\"11\" ry=\"5.5\" fill=\"#8d5a2b\"/>' +\n      '<ellipse cy=\"2.2\" rx=\"7\" ry=\"2.4\" fill=\"#b07a45\"/>' +\n      '<path d=\"M7-2l5-7\" stroke=\"#8d5a2b\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>' +\n      '<ellipse cx=\"14.5\" cy=\"-10\" rx=\"4.2\" ry=\"3\" fill=\"#8d5a2b\"/>' +\n      '<ellipse cx=\"12\" cy=\"-12.3\" rx=\"1.6\" ry=\".8\" fill=\"#6b4420\"/>' +\n      '<circle cx=\"18.4\" cy=\"-9.4\" r=\"1.1\" fill=\"#15161a\"/>' +\n      '<circle cx=\"14.8\" cy=\"-10.8\" r=\".6\" fill=\"#15161a\"/>' +\n      '<path d=\"M12.5-12.5l-2-5.5m.8 2.7l-2.8-1.2M14.5-12.8l1-5.7m-.4 2.5l2.7-1.2\" stroke=\"#5c3a1a\" stroke-width=\"1.1\" stroke-linecap=\"round\" fill=\"none\"/>' +\n      '<path d=\"M6.5-3.5q4 3 8.5-3\" stroke=\"#c92a2a\" stroke-width=\"1.3\" fill=\"none\"/>' +\n    '</g>';\n\n  var TRENO_SVG =\n    '<svg viewBox=\"0 0 150 48\" aria-hidden=\"true\">' +\n      // rédeas e tirante com sininhos\n      '<path d=\"M49 16.5Q66 22 80 21.5L118 18.5\" stroke=\"#3b2a1a\" stroke-width=\".9\" fill=\"none\"/>' +\n      '<path d=\"M56 29L77 28.5L114 26.5\" stroke=\"#3b2a1a\" stroke-width=\"1.2\" fill=\"none\"/>' +\n      '<g class=\"rena\" transform=\"translate(88 27)\">' + RENA + '</g>' +\n      '<g class=\"rena rena-2\" transform=\"translate(126 25)\">' + RENA + '</g>' +\n      '<g class=\"sino\"><circle cx=\"66\" cy=\"30.2\" r=\"1.6\" fill=\"#f08c00\" stroke=\"#a35f00\" stroke-width=\".5\"/></g>' +\n      '<g class=\"sino sino-2\"><circle cx=\"103\" cy=\"28.6\" r=\"1.6\" fill=\"#f08c00\" stroke=\"#a35f00\" stroke-width=\".5\"/></g>' +\n      // saco de presentes (com um presentinho aparecendo)\n      '<g class=\"saco\">' +\n        '<rect x=\"9\" y=\"3.5\" width=\"6\" height=\"5\" rx=\".6\" fill=\"#2b8a3e\" transform=\"rotate(-12 12 6)\"/>' +\n        '<path d=\"M6 21Q3 9 13 6q10 3 7 15z\" fill=\"#8d5a2b\" stroke=\"#5c3a1a\" stroke-width=\".8\"/>' +\n        '<path d=\"M10 8l3-2.2 3 2.2\" stroke=\"#5c3a1a\" stroke-width=\".9\" fill=\"none\"/>' +\n      '</g>' +\n      // Papai Noel\n      '<ellipse cx=\"33\" cy=\"19\" rx=\"9\" ry=\"7\" fill=\"#c92a2a\"/>' +\n      '<g class=\"braco-aceno\">' +\n        '<path d=\"M29.5 15.5l-4.5-8\" stroke=\"#c92a2a\" stroke-width=\"3.2\" stroke-linecap=\"round\"/>' +\n        '<circle cx=\"24.6\" cy=\"6.6\" r=\"1.8\" fill=\"#15161a\"/>' +\n      '</g>' +\n      '<circle cx=\"36\" cy=\"10\" r=\"3.6\" fill=\"#f5c9a5\"/>' +\n      '<circle cx=\"38.4\" cy=\"11\" r=\"1\" fill=\"#f08c8c\" fill-opacity=\".8\"/>' +\n      '<path d=\"M32.5 10.5Q36 20 40.5 10.5q-2.5 2-4 2t-4-2z\" fill=\"#fff\"/>' +\n      '<path d=\"M35.3 11.6q1.6-1 3.6 0q-1.8 1.1-3.6 0z\" fill=\"#f1f3f5\"/>' +\n      '<path d=\"M32 8.5q2-7 9-5l-.8 4.5z\" fill=\"#c92a2a\"/>' +\n      '<rect x=\"31.6\" y=\"7.3\" width=\"9.2\" height=\"2.2\" rx=\"1.1\" fill=\"#fff\"/>' +\n      '<circle cx=\"41.6\" cy=\"3.6\" r=\"1.7\" fill=\"#fff\"/>' +\n      '<circle cx=\"37.3\" cy=\"9.6\" r=\".6\" fill=\"#15161a\"/>' +\n      '<path d=\"M38 17l10-.5\" stroke=\"#c92a2a\" stroke-width=\"3.2\" stroke-linecap=\"round\"/>' +\n      '<circle cx=\"49\" cy=\"16.5\" r=\"1.8\" fill=\"#15161a\"/>' +\n      // trenó\n      '<path d=\"M3 12q6-2 8 5l1 4h35q10 0 10 8t-10 8H11q-8 0-8-8z\" fill=\"#c92a2a\" stroke=\"#7a1414\"/>' +\n      '<path d=\"M6 25.5h46\" stroke=\"#ffd43b\" stroke-width=\"1.6\"/>' +\n      '<path d=\"M16 31.5q3-3.5 6 0t6 0 6 0 6 0\" stroke=\"#ffd43b\" stroke-width=\"1\" fill=\"none\"/>' +\n      '<path d=\"M10 37v5M44 37v5\" stroke=\"#3b2a1a\" stroke-width=\"1.6\"/>' +\n      '<path d=\"M2 42h50q8 0 8-7q0-3-3-3\" stroke=\"#3b2a1a\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/>' +\n    '</svg>';\n\n  function box(el) {\n    var r = el.getBoundingClientRect();\n    return { left: r.left + window.scrollX, top: r.top + window.scrollY, width: r.width, height: r.height, bottom: r.bottom + window.scrollY };\n  }\n  function clamp01(v) { return Math.max(0, Math.min(1, v)); }\n  function smooth(v) { return v * v * (3 - 2 * v); }\n\n  // O presente fica no lugar da bolinha, dentro do link do logo.\n  var presente = document.createElement('span');\n  presente.className = 'ipc-natal-presente';\n  presente.setAttribute('aria-hidden', 'true');\n  presente.innerHTML = PRESENTE_SVG;\n  ball.parentNode.appendChild(presente);\n\n  /* ================= Bonequinho de login: se veste de Papai Noel ================= */\n  // O bonequinho começa preto (o original). Quando o trenó passa, o Papai Noel joga\n  // a roupa e ele se veste: casaco, cinto, rosto com barba e, por último, o gorro.\n  // O ícone é uma máscara (icon-user.svg, 23x26) em 30x30 com \"contain\"; a roupa usa\n  // o mesmo viewBox, então cobre a silhueta certinho.\n  var roupaNoel = (function () {\n    var icone = document.querySelector('.user-info .icon-user');\n    if (!icone) return null;\n    var CORPO = 'M15.925 14.625H15.077C13.9496 15.143 12.6953 15.4375 11.375 15.4375C10.0547 15.4375 8.80547 15.143 7.67305 14.625H6.825C3.05703 14.625 0 17.682 0 21.45V23.5625C0 24.9082 1.0918 26 2.4375 26H20.3125C21.6582 26 22.75 24.9082 22.75 23.5625V21.45C22.75 17.682 19.693 14.625 15.925 14.625Z';\n    var svg =\n      '<svg class=\"ipc-natal-user\" viewBox=\"0 0 23 26\" aria-hidden=\"true\">' +\n        '<defs><clipPath id=\"ipc-natal-corpo\"><path d=\"' + CORPO + '\"/></clipPath></defs>' +\n        // casaco vermelho com barra de pelúcia, faixa do meio e cinto\n        '<g class=\"roupa-casaco\">' +\n          '<path d=\"' + CORPO + '\" fill=\"#c92a2a\"/>' +\n          '<g clip-path=\"url(#ipc-natal-corpo)\">' +\n            '<rect x=\"10.1\" y=\"14\" width=\"2.55\" height=\"9\" fill=\"#fff\"/>' +\n            '<rect x=\"0\" y=\"19.3\" width=\"22.75\" height=\"2.3\" fill=\"#15161a\"/>' +\n            '<rect x=\"0\" y=\"22.7\" width=\"22.75\" height=\"3.3\" fill=\"#fff\"/>' +\n          '</g>' +\n          '<path d=\"' + CORPO + '\" fill=\"none\" stroke=\"#7a1414\" stroke-width=\".45\"/>' +\n        '</g>' +\n        '<rect class=\"fivela\" x=\"9.5\" y=\"18.9\" width=\"3.75\" height=\"3.1\" rx=\".5\" fill=\"none\" stroke=\"#f2b705\" stroke-width=\".9\"/>' +\n        // rosto com barba descendo até o peito, bigode e nariz\n        '<g class=\"roupa-rosto\">' +\n          '<circle cx=\"11.375\" cy=\"6.5\" r=\"6.5\" fill=\"#f5c9a5\" stroke=\"#b07a55\" stroke-width=\".35\"/>' +\n          '<circle cx=\"7.9\" cy=\"7.4\" r=\"1\" fill=\"#f08c8c\" fill-opacity=\".65\"/>' +\n          '<circle cx=\"14.85\" cy=\"7.4\" r=\"1\" fill=\"#f08c8c\" fill-opacity=\".65\"/>' +\n          '<circle cx=\"9.1\" cy=\"5.8\" r=\".62\" fill=\"#15161a\"/>' +\n          '<circle cx=\"13.65\" cy=\"5.8\" r=\".62\" fill=\"#15161a\"/>' +\n          '<path d=\"M4.9 6.9Q5.1 15.9 11.375 16.9 17.65 15.9 17.85 6.9 16.3 9.7 14.3 9.3 11.375 11.3 8.45 9.3 6.45 9.7 4.9 6.9z\" fill=\"#fff\" stroke=\"#ced4da\" stroke-width=\".35\"/>' +\n          '<path d=\"M8.1 9.5q1.7-1.3 3.275-.15Q12.95 8.2 14.65 9.5 12.9 10.6 11.375 10 9.85 10.6 8.1 9.5z\" fill=\"#f1f3f5\" stroke=\"#ced4da\" stroke-width=\".3\"/>' +\n          '<circle cx=\"11.375\" cy=\"8.1\" r=\".95\" fill=\"#e8a07a\"/>' +\n        '</g>' +\n        // gorro com pompom\n        '<g class=\"gorro\">' +\n          '<path d=\"M5 3.4Q6.4-4.8 13.4-5.3 19.4-5.2 21-.6 18.6-2.4 16.8-1.2L17.8 3.4z\" fill=\"#c92a2a\" stroke=\"#7a1414\" stroke-width=\".4\"/>' +\n          '<g class=\"pompom\"><circle cx=\"21.2\" cy=\"-.2\" r=\"1.9\" fill=\"#fff\" stroke=\"#ced4da\" stroke-width=\".35\"/></g>' +\n          '<rect x=\"4.1\" y=\"2.2\" width=\"14.6\" height=\"2.7\" rx=\"1.35\" fill=\"#fff\" stroke=\"#ced4da\" stroke-width=\".35\"/>' +\n        '</g>' +\n      '</svg>';\n    icone.insertAdjacentHTML('afterend', svg);\n    var boneco = icone.nextElementSibling;\n\n    // Mesma caixa do ícone original (muda nos pontos de quebra do layout).\n    function alinhar() {\n      boneco.style.left = icone.offsetLeft + 'px';\n      boneco.style.top = icone.offsetTop + 'px';\n      boneco.style.width = icone.offsetWidth + 'px';\n      boneco.style.height = icone.offsetHeight + 'px';\n    }\n    alinhar();\n    window.addEventListener('resize', alinhar);\n\n    function parte(sel) { return boneco.querySelector(sel); }\n\n    // Com \"reduzir movimento\" (ou se o trenó não passar pelo ícone) já aparece vestido.\n    return {\n      icone: icone,\n      // Veste o bonequinho começando em `t` segundos a partir de agora.\n      vestir: function (t) {\n        var ms = function (s) { return (t + s) * 1000; };\n        var opc = { fill: 'both', easing: 'ease-out' };\n        parte('.roupa-casaco').animate([\n          { opacity: 0, transform: 'scaleY(0)' },\n          { opacity: 1, transform: 'scaleY(1.08)', offset: 0.7 },\n          { opacity: 1, transform: 'scaleY(1)' }\n        ], Object.assign({ duration: 500, delay: ms(0.05) }, opc));\n        parte('.fivela').animate([\n          { opacity: 0, transform: 'scale(0)' },\n          { opacity: 1, transform: 'scale(1.5)', offset: 0.6 },\n          { opacity: 1, transform: 'scale(1)' }\n        ], Object.assign({ duration: 300, delay: ms(0.5) }, opc));\n        parte('.roupa-rosto').animate([\n          { opacity: 0, transform: 'scale(.5)' },\n          { opacity: 1, transform: 'scale(1.1)', offset: 0.65 },\n          { opacity: 1, transform: 'scale(1)' }\n        ], Object.assign({ duration: 450, delay: ms(0.6) }, opc));\n        parte('.gorro').animate([\n          { opacity: 0, transform: 'translateY(-9px) rotate(-14deg)' },\n          { opacity: 1, offset: 0.35 },\n          { opacity: 1, transform: 'translateY(0) rotate(0)' }\n        ], { duration: 750, delay: ms(1.0), fill: 'both', easing: 'cubic-bezier(.34,1.56,.64,1)' });\n        parte('.pompom').animate([\n          { transform: 'rotate(0)' }, { transform: 'rotate(22deg)' }, { transform: 'rotate(-14deg)' },\n          { transform: 'rotate(7deg)' }, { transform: 'rotate(0)' }\n        ], { duration: 1400, delay: ms(1.6), fill: 'both', easing: 'ease-in-out' });\n        // pulinho de alegria, com o ícone preto por baixo junto\n        [boneco, icone].forEach(function (el) {\n          el.animate([\n            { transform: 'translateY(0)' }, { transform: 'translateY(-4px)', offset: 0.4 },\n            { transform: 'translateY(0)', offset: 0.75 }, { transform: 'translateY(-1.5px)', offset: 0.88 },\n            { transform: 'translateY(0)' }\n          ], { duration: 550, delay: ms(1.75), easing: 'ease-in-out' });\n        });\n      }\n    };\n  })();\n\n  if (reduceMotion) return;\n\n  // A roupa fica escondida até o Papai Noel jogar (as animações começam invisíveis).\n  if (roupaNoel) {\n    document.querySelectorAll('.ipc-natal-user .roupa-casaco, .ipc-natal-user .fivela, .ipc-natal-user .roupa-rosto, .ipc-natal-user .gorro')\n      .forEach(function (el) { el.style.opacity = '0'; });\n    // PRÉVIA: por enquanto se veste sozinho; depois quem dispara é a roupa jogada do trenó.\n    roupaNoel.vestir(3.5);\n  }\n\n  /* ================= Neve no cabeçalho ================= */\n  (function neve() {\n    // O fundo preto da barra de cima passa a ser pintado pelo próprio cabeçalho\n    // (degradê duro preto/amarelo), assim a neve fica entre o fundo e o conteúdo.\n    var corPreta = black ? getComputedStyle(black).backgroundColor : '#15161a';\n    var corAmarela = getComputedStyle(header).backgroundColor;\n    header.style.setProperty('--ipc-preto', corPreta);\n    header.style.setProperty('--ipc-amarelo', corAmarela);\n    header.classList.add('ipc-natal-hdr');\n    if (black) black.classList.add('ipc-natal-transp');\n\n    var canvas = document.createElement('canvas');\n    canvas.className = 'ipc-natal-neve';\n    canvas.setAttribute('aria-hidden', 'true');\n    header.insertBefore(canvas, header.firstChild);\n    var ctx = canvas.getContext('2d');\n\n    var W = 0, H = 0, flocos = [];\n    function novoFloco(topo) {\n      var r = 0.8 + Math.pow(Math.random(), 2) * 2.2;   // poucos flocos grandes\n      return {\n        base: Math.random() * W,\n        y: topo ? -5 : Math.random() * H,\n        r: r,\n        vy: 12 + r * 11 + Math.random() * 6,          // os maiores caem mais rápido\n        amp: 6 + Math.random() * 16,\n        freq: 0.4 + Math.random() * 0.8,\n        fase: Math.random() * Math.PI * 2,\n        a: 0.7 + Math.random() * 0.3\n      };\n    }\n    function medir() {\n      var r = header.getBoundingClientRect();\n      var dpr = Math.min(2, window.devicePixelRatio || 1);\n      W = r.width; H = r.height;\n      canvas.width = Math.round(W * dpr);\n      canvas.height = Math.round(H * dpr);\n      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n      header.style.setProperty('--ipc-h1', (black ? black.offsetHeight : 0) + 'px');\n      var qtd = Math.max(30, Math.min(160, Math.round(W * H / 1800)));\n      while (flocos.length < qtd) flocos.push(novoFloco(false));\n      flocos.length = qtd;\n    }\n    medir();\n    if (window.ResizeObserver) new ResizeObserver(medir).observe(header);\n\n    var visivel = true, rodando = false, antes = 0, relogio = 0;\n    function quadro(agora) {\n      if (!visivel) { rodando = false; return; }\n      var dt = Math.min(0.05, (agora - antes) / 1000 || 0);\n      antes = agora;\n      relogio += dt;\n      ctx.clear