em\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio fixo com freio\"></div>\n      <div class=\"product-name\">Rodízio fixo com freio</div>\n      <div class=\"ipc-card-price\"><span>R$ 24,50</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-15%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Roda de gel 75 mm\"></div>\n      <div class=\"product-name\">Roda de gel 75 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 31,00</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n","criadoEm":1790618700000,"css":"/* ---------- 4. Logo: bolinha desce a escada e volta com um super impulso ---------- */\n/* Medidas em % da imagem original (205x90): bolinha em x50 y2, 16px.\n   Nos translate, 100% = diâmetro da bolinha. Degraus: barra 2 (topo y43),\n   barra 1 (topo y66), chão (y88). Roda uma vez por carregamento.\n   A altura dos pulos vem de --ipc-ball-apex / --ipc-ball-hop, calculadas no JS\n   para a bolinha nunca sair da faixa amarela (sem JS: pulo baixo). */\n.logo a.ipc-logo-anim {\n  position: relative;\n}\n.ipc-logo-ball {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  background: #15161a;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n  animation: ipc-ball-escada 2.6s .6s 1 both;\n}\n@keyframes ipc-ball-escada {\n  0%   { transform: translate(0, 0) scale(1);               animation-timing-function: ease-out; }\n  5%   { transform: translate(0, 0) scale(1.18, .82);        animation-timing-function: ease-out; }\n  12%  { transform: translate(-60%, var(--ipc-ball-hop, -10%)) scale(.95, 1.05);  animation-timing-function: ease-in; }\n  21%  { transform: translate(-109%, 156%) scale(1);          animation-timing-function: ease-out; }\n  23%  { transform: translate(-109%, 156%) scale(1.25, .75); animation-timing-function: ease-out; }\n  31%  { transform: translate(-165%, 95%) scale(1);          animation-timing-function: ease-in; }\n  40%  { transform: translate(-216%, 300%) scale(1);          animation-timing-function: ease-out; }\n  42%  { transform: translate(-216%, 300%) scale(1.25, .75); animation-timing-function: ease-out; }\n  50%  { transform: translate(-268%, 235%) scale(1);          animation-timing-function: ease-in; }\n  59%  { transform: translate(-312%, 437%) scale(1);          animation-timing-function: ease-out; }\n  62%  { transform: translate(-312%, 437%) scale(1.3, .7);    animation-timing-function: ease-in-out; }\n  /* carregando o impulso */\n  70%  { transform: translate(-312%, 437%) scale(1.55, .45); animation-timing-function: cubic-bezier(.15, .9, .3, 1); }\n  /* super impulso: estica na subida */\n  76%  { transform: translate(-230%, 60%) scale(.72, 1.45);  animation-timing-function: ease-out; }\n  84%  { transform: translate(-90%, var(--ipc-ball-apex, -10%)) scale(.95, 1.08); animation-timing-function: ease-in; }\n  93%  { transform: translate(0, 0) scale(1.3, .72);          animation-timing-function: ease-out; }\n  97%  { transform: translate(0, calc(var(--ipc-ball-hop, -10%) * .4)) scale(.94, 1.06);      animation-timing-function: ease-in; }\n  100% { transform: translate(0, 0) scale(1); }\n}\n@media (prefers-reduced-motion: reduce) { .ipc-logo-ball { animation: none; } }\n\n/* ===== pascoa ===== */\n/* Tema de Páscoa — IPC Comercial (cópia local)\n * Ativado pela classe body.ipc-pascoa (colocada pelo pascoa.js).\n * Para desligar: ATIVO = false no pascoa.js (ou remova as duas linhas no index.html). */\n\n/* A bolinha do \"i\" some: quem vira o pingo é o ovo que o coelho bota. */\nbody.ipc-pascoa .ipc-logo-ball {\n  visibility: hidden;\n  animation: none;\n}\n\n/* ---------- Ovo (mesma caixa da bolinha do logo) ---------- */\n.ipc-pascoa-ovo {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n}\n.ipc-pascoa-ovo svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n\n/* ---------- Coelho ---------- */\n.ipc-pascoa-coelho {\n  position: absolute;\n  left: 0;\n  top: 0;\n  z-index: 2;\n  pointer-events: none;\n}\n.ipc-pascoa-coelho-corpo {\n  width: 100%;\n  height: 100%;\n  transform-origin: 50% 100%;\n}\n.ipc-pascoa-coelho svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n/* Orelhas balançando enquanto pula */\n.ipc-pascoa-coelho .orelha {\n  transform-box: fill-box;\n  transform-origin: 50% 95%;\n  animation: ipc-pascoa-orelha .65s ease-in-out infinite alternate;\n}\n.ipc-pascoa-coelho .orelha-2 { animation-delay: -.32s; }\n@keyframes ipc-pascoa-orelha {\n  from { transform: rotate(-9deg); }\n  to   { transform: rotate(7deg); }\n}\n/* Rabinho mexendo na hora de botar o ovo */\n.ipc-pascoa-coelho .rabo {\n  transform-box: fill-box;\n  transform-origin: 80% 50%;\n}\n.ipc-pascoa-coelho.botando .rabo {\n  animation: ipc-pascoa-rabo .16s ease-in-out 8 alternate;\n}\n/* O ovo rosa sai da cesta (é ele que vira o pingo do \"i\") */\n.ipc-pascoa-coelho .ovo-cesta {\n  transform-box: fill-box;\n  transform-origin: 50% 100%;\n  transition: transform .4s ease-in, opacity .4s ease-in;\n}\n.ipc-pascoa-coelho.sem-ovo .ovo-cesta {\n  transform: translateY(-3px) scale(0);\n  opacity: 0;\n}\n@keyframes ipc-pascoa-rabo {\n  from { transform: translateY(-.8px) rotate(-14deg); }\n  to   { transform: translateY(.8px) rotate(14deg); }\n}\n\n/* Brilhinhos quando o ovo aparece */\n.ipc-pascoa-brilho {\n  position: absolute;\n  margin: -4px 0 0 -4px;\n  font-size: 9px;\n  line-height: 1;\n  pointer-events: none;\n  animation: ipc-pascoa-brilho .8s ease-out 1 both;\n}\n@keyframes ipc-pascoa-brilho {\n  0%   { transform: translate(0, 0) scale(.3) rotate(0); opacity: 0; }\n  25%  { transform: translate(calc(var(--dx) * .35), calc(var(--dy) * .35)) scale(1.1) rotate(45deg); opacity: 1; }\n  100% { transform: translate(var(--dx), var(--dy)) scale(.3) rotate(140deg); opacity: 0; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ipc-pascoa-coelho, .ipc-pascoa-brilho { display: none; }\n}\n","descricao":"Um coelho azul, branco e rosa sobe os três pauzinhos do logo e bota um ovo no lugar do pingo do \"i\". Precisa da bolinha do logo (já inclusa aqui).","html":"<a href=\"/\" class=\"ipc-logo-anim\"><img src=\"data:image/png;base64,\" alt=\"IPC Comercial\" title=\"IPC Comercial\"><span class=\"ipc-logo-ball\" aria-hidden=\"true\"></span></a>","js":"/* Bolinha do logo: limita a altura dos pulos ao espaço amarelo acima dela */\n(function fitLogoBall() {\n  var ball = document.querySelector('.ipc-logo-ball');\n  if (!ball) return;\n  var blackBar = document.querySelector('#header-main .header-1');\n  var r = ball.getBoundingClientRect();\n  var d = r.width;\n  if (!d) return;\n  var limit = blackBar ? blackBar.getBoundingClientRect().bottom : r.top - d;\n  var margin = 4;\n  // No ápice a bolinha estica 8% para cima (scale 1.08 com origem embaixo).\n  var room = r.top - limit - margin - d * 0.08;\n  var apex = Math.max(-330, Math.min(0, -room / d * 100));\n  var hop = Math.max(apex, -70);\n  ball.style.setProperty('--ipc-ball-apex', apex.toFixed(1) + '%');\n  ball.style.setProperty('--ipc-ball-hop', hop.toFixed(1) + '%');\n})();\n\n/* ===== pascoa ===== */\n/* Tema de Páscoa — IPC Comercial (cópia local)\n * Um coelho azul, branco e rosa entra pulando pela esquerda, sobe os 3 pauzinhos\n * do logo (barra baixa, barra do meio e a haste do \"i\"), bota um ovo no lugar do\n * pingo do \"i\" e volta pulando para a esquerda. O ovo fica como pingo do \"i\".\n * Roda uma vez por carregamento. Para desligar: ATIVO = false. */\n(function () {\n  var ATIVO = true;\n  // ?tema=... na URL escolhe o tema (para comparar os temas em abas separadas).\n  var temaUrl = new URLSearchParams(location.search).get('tema');\n  if (temaUrl) ATIVO = temaUrl === 'pascoa';\n  if (!ATIVO) return;\n\n  var ball = document.querySelector('.ipc-logo-ball');\n  var header = document.querySelector('#header-main');\n  var logo = document.querySelector('.logo img');\n  if (!ball || !header || !logo) return;\n  var ancora = ball.parentNode;               // o link do logo (position: relative)\n  document.body.classList.add('ipc-pascoa');\n\n  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  var OVO_SVG =\n    '<svg viewBox=\"0 0 16 16\" aria-hidden=\"true\">' +\n      '<defs><clipPath id=\"ipc-ovo-clip\"><ellipse cx=\"8\" cy=\"9\" rx=\"6\" ry=\"7\"/></clipPath></defs>' +\n      '<ellipse cx=\"8\" cy=\"9\" rx=\"6\" ry=\"7\" fill=\"#f783ac\"/>' +\n      '<g clip-path=\"url(#ipc-ovo-clip)\">' +\n        '<path d=\"M1.5 8.4l1.7-1.5 1.7 1.5 1.7-1.5 1.7 1.5 1.7-1.5 1.7 1.5 1.7-1.5 1.7 1.5\" stroke=\"#fff\" stroke-width=\"1.1\" fill=\"none\" stroke-linejoin=\"round\"/>' +\n        '<rect x=\"0\" y=\"10.6\" width=\"16\" height=\"1.8\" fill=\"#74c0fc\"/>' +\n        '<circle cx=\"5\" cy=\"13.7\" r=\".75\" fill=\"#fff\"/><circle cx=\"8\" cy=\"14.4\" r=\".75\" fill=\"#fff\"/><circle cx=\"11\" cy=\"13.7\" r=\".75\" fill=\"#fff\"/>' +\n      '</g>' +\n      '<ellipse cx=\"5.4\" cy=\"5.4\" rx=\"1.1\" ry=\"1.9\" fill=\"#fff\" fill-opacity=\".55\" transform=\"rotate(20 5.4 5.4)\"/>' +\n      '<ellipse cx=\"8\" cy=\"9\" rx=\"6\" ry=\"7\" fill=\"none\" stroke=\"#c2255c\" stroke-width=\".5\"/>' +\n    '</svg>';\n\n  // Coelho de perfil virado para a direita; os pés tocam o chão em y = 46.\n  var AZUL = '#5aa9e6', AZUL_ESCURO = '#4a97d4', CONTORNO = '#2f6fa8', ROSA = '#f783ac';\n  var COELHO_SVG =\n    '<svg viewBox=\"0 0 46 46\" aria-hidden=\"true\">' +\n      '<g class=\"orelha orelha-2\">' +\n        '<ellipse cx=\"23\" cy=\"11\" rx=\"3\" ry=\"9\" fill=\"' + AZUL_ESCURO + '\" stroke=\"' + CONTORNO + '\" stroke-width=\".7\" transform=\"rotate(-16 23 18)\"/>' +\n        '<ellipse cx=\"23\" cy=\"11.5\" rx=\"1.4\" ry=\"6.3\" fill=\"' + ROSA + '\" transform=\"rotate(-16 23 18)\"/>' +\n      '</g>' +\n      '<circle class=\"rabo\" cx=\"7\" cy=\"36\" r=\"4.5\" fill=\"#fff\" stroke=\"#cfd8e3\" stroke-width=\".6\"/>' +\n      '<ellipse cx=\"17\" cy=\"35\" rx=\"11\" ry=\"9\" fill=\"' + AZUL + '\" stroke=\"' + CONTORNO + '\" stroke-width=\".8\"/>' +\n      '<ellipse cx=\"12\" cy=\"40\" rx=\"6\" ry=\"5\" fill=\"' + AZUL_ESCURO + '\" stroke=\"' + CONTORNO + '\" stroke-width=\".7\"/>' +\n      '<ellipse cx=\"22\" cy=\"37\" rx=\"6\" ry=\"6\" fill=\"#fff\"/>' +\n      '<ellipse cx=\"15\" cy=\"44.2\" rx=\"6.5\" ry=\"1.8\" fill=\"#fff\" stroke=\"#cfd8e3\" stroke-width=\".6\"/>' +\n      '<ellipse cx=\"26\" cy=\"44.3\" rx=\"3\" ry=\"1.6\" fill=\"#fff\" stroke=\"#cfd8e3\" stroke-width=\".6\"/>' +\n      '<circle cx=\"28\" cy=\"23\" r=\"8\" fill=\"' + AZUL + '\" stroke=\"' + CONTORNO + '\" stroke-width=\".8\"/>' +\n      '<g class=\"orelha\">' +\n        '<ellipse cx=\"29\" cy=\"9\" rx=\"3.2\" ry=\"9.5\" fill=\"' + AZUL + '\" stroke=\"' + CONTORNO + '\" stroke-width=\".7\" transform=\"rotate(10 29 17)\"/>' +\n        '<ellipse cx=\"29\" cy=\"9.6\" rx=\"1.6\" ry=\"7\" fill=\"' + ROSA + '\" transform=\"rotate(10 29 17)\"/>' +\n      '</g>' +\n      '<ellipse cx=\"33.5\" cy=\"26\" rx=\"3.6\" ry=\"2.8\" fill=\"#fff\"/>' +\n      '<circle cx=\"29.4\" cy=\"26.2\" r=\"1.4\" fill=\"' + ROSA + '\" fill-opacity=\".7\"/>' +\n      '<circle cx=\"31\" cy=\"21\" r=\"1.4\" fill=\"#1c1f26\"/>' +\n      '<circle cx=\"31.5\" cy=\"20.5\" r=\".45\" fill=\"#fff\"/>' +\n      '<ellipse cx=\"36.4\" cy=\"24.8\" rx=\"1.3\" ry=\"1\" fill=\"#e64980\"/>' +\n      '<path d=\"M35.6 27.1q-.8.9-1.8.4\" stroke=\"#1c1f26\" stroke-width=\".5\" fill=\"none\" stroke-linecap=\"round\"/>' +\n      // cesta de vime com 3 ovos (o rosa é o que vai para o pingo do \"i\")\n      '<g class=\"cesta\">' +\n        '<ellipse cx=\"34\" cy=\"32.4\" rx=\"2\" ry=\"2.6\" fill=\"#74c0fc\" stroke=\"#1971c2\" stroke-width=\".4\"/>' +\n        '<ellipse class=\"ovo-cesta\" cx=\"37.6\" cy=\"31.6\" rx=\"2.1\" ry=\"2.8\" fill=\"#f783ac\" stroke=\"#c2255c\" stroke-width=\".4\"/>' +\n        '<ellipse cx=\"41.2\" cy=\"32.4\" rx=\"2\" ry=\"2.6\" fill=\"#b197fc\" stroke=\"#7048e8\" stroke-width=\".4\"/>' +\n        '<path d=\"M31.8 33.6Q37.5 27.2 43.2 33.6\" stroke=\"#8a5a2b\" stroke-width=\"1.1\" fill=\"none\"/>' +\n        '<path d=\"M31 34.6h13l-1.6 7.6q-4.9 1.4-9.8 0z\" fill=\"#c68642\" stroke=\"#8a5a2b\" stroke-width=\".6\"/>' +\n        '<path d=\"M31.6 37.2h11.8M32.2 39.8h10.6M35 34.8l.4 7.8M38.5 34.8l-.2 8M41.5 34.8l-.6 7.6\" stroke=\"#8a5a2b\" stroke-width=\".45\" stroke-opacity=\".7\"/>' +\n        '<rect x=\"30.4\" y=\"33.2\" width=\"14.2\" height=\"2\" rx=\"1\" fill=\"#a86b33\" stroke=\"#8a5a2b\" stroke-width=\".5\"/>' +\n      '</g>' +\n      // braço segurando a alça da cesta\n      '<path d=\"M23.5 32.5q4 3.2 8.2 1.4\" stroke=\"' + AZUL + '\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>' +\n      '<circle cx=\"31.8\" cy=\"33.8\" r=\"1.5\" fill=\"#fff\" stroke=\"#cfd8e3\" stroke-width=\".5\"/>' +\n    '</svg>';\n\n  // O ovo fica no lugar da bolinha, dentro do link do logo.\n  var ovo = document.createElement('span');\n  ovo.className = 'ipc-pascoa-ovo';\n  ovo.setAttribute('aria-hidden', 'true');\n  ovo.innerHTML = OVO_SVG;\n  ancora.appendChild(ovo);\n\n  if (reduceMotion) return;\n  ovo.style.opacity = '0';\n\n  /* ---------- Geometria em pixels do PNG do logo (205x90) ---------- */\n  // Chão = base do logo (y 88). Topos: barra baixa y 66 (x 17–30),\n  // barra do meio y 43 (x 34–47), haste do \"i\" y 24 (x 51–64).\n  var CHAO = 88, BARRA1 = [23.5, 66], BARRA2 = [40.5, 43], HASTE = [57.5, 24];\n\n  var lr = logo.getBoundingClientRect();\n  var s = lr.width / 205;                     // px de tela por px do PNG\n  var black = document.querySelector('#header-main .header-1');\n  var topoFaixa = black ? black.getBoundingClientRect().bottom : header.getBoundingClientRect().top;\n  // O ponto mais alto permitido (em px do PNG, relativo ao topo do logo): 2 px abaixo do preto.\n  var topoPermitido = (topoFaixa + 2 - lr.top) / s;\n\n  var ESTICA = 1.12;                          // o coelho estica no ar\n  // Altura do coelho: até 28 px do PNG, menor se não couber em pé sobre a haste.\n  var alt = Math.min(28, (HASTE[1] - topoPermitido - 1) / ESTICA);\n  var larg = alt;                             // SVG quadrado (46x46) por causa da cesta\n  // Os pés ficam em x 20,5 de 46 (a cesta deixa o desenho mais largo na frente).\n  var PES = 20.5 / 46;\n  var xEntrada = -(lr.left - header.getBoundingClientRect().left) / s - larg;\n\n  var coelho = document.createElement('span');\n  coelho.className = 'ipc-pascoa-coelho';\n  coelho.setAttribute('aria-hidden', 'true');\n  coelho.style.width = larg * s + 'px';\n  coelho.style.height = alt * s + 'px';\n  coelho.innerHTML = '<span class=\"ipc-pascoa-coelho-corpo\" style=\"display:block\">' + COELHO_SVG + '</span>';\n  var corpo = coelho.firstChild;\n  ancora.appendChild(coelho);\n\n  /* ---------- Roteiro: pulos, pausa para botar o ovo e volta ---------- */\n  // Tempos em segundos (versão mais calma: pulos longos e pausas em cada degrau).\n  var roteiro = [\n    { pulo: [[xEntrada, CHAO], [-45, CHAO]], dur: 0.7, altura: 9 },\n    { espera: 0.12 },\n    { pulo: [[-45, CHAO], [4, CHAO]], dur: 0.7, altura: 9 },\n    { espera: 0.3 },\n    { pulo: [[4, CHAO], BARRA1], dur: 0.65, altura: 8 },\n    { espera: 0.35 },\n    { pulo: [BARRA1, BARRA2], dur: 0.65, altura: 8 },\n    { espera: 0.35 },\n    { pulo: [BARRA2, HASTE], dur: 0.65, altura: 8 },\n    { bota: 1.4 },\n    { espera: 0.2 },\n    { vira: true },\n    { espera: 0.15 },\n    { pulo: [HASTE, [-8, CHAO]], dur: 0.9, altura: 7, soltaOvo: true },\n    { espera: 0.2 },\n    { pulo: [[-8, CHAO], [-50, CHAO]], dur: 0.7, altura: 9 },\n    { espera: 0.12 },\n    { pulo: [[-50, CHAO], [xEntrada, CHAO]], dur: 0.7, altura: 9 }\n  ];\n\n  var ATRASO = 0.6;\n  var FPS = 60;\n  var pos = [], pose = [];\n  var t = 0, dir = 1, tSoltaOvo = 0, tBota = 0;\n  var ultimo = [xEntrada, CHAO];\n\n  function empurra(x, y, sx, sy) {\n    pos.push({ x: x, y: y });\n    pose.push({ sx: sx * dir, sy: sy });\n  }\n\n  roteiro.forEach(function (p) {\n    var n, i;\n    if (p.espera) {\n      n = Math.round(p.espera * FPS);\n      for (i = 0; i < n; i++) empurra(ultimo[0], ultimo[1], 1, 1);\n    } else if (p.bota) {\n      // agacha, treme um pouquinho e mexe o rabo\n      tBota = pos.length / FPS;\n      n = Math.round(p.bota * FPS);\n      for (i = 0; i < n; i++) {\n        var u = i / n;\n        var agacha = Math.sin(Math.PI * Math.min(1, u * 1.25)) * 0.14;\n        var treme = Math.sin(u * 60) * 0.25 * (u > 0.2 && u < 0.8 ? 1 : 0);\n        empurra(ultimo[0] + treme, ultimo[1], 1 + agacha * 0.7, 1 - agacha);\n      }\n    } else if (p.vira) {\n      dir = -dir;\n    } else if (p.pulo) {\n      var a = p.pulo[0], b = p.pulo[1];\n      if (p.soltaOvo) tSoltaOvo = pos.length / FPS;\n      // ápice: um pouco acima do ponto mais alto, sem passar da faixa amarela\n      var apice = Math.min(a[1], b[1]) - p.altura;\n      apice = Math.max(apice, topoPermitido + alt * ESTICA);\n      apice = Math.min(apice, Math.min(a[1], b[1]));\n      var d0 = a[1] - apice, d1 = b[1] - apice;\n      var bb = -2 * d0 - 2 * Math.sqrt(Math.max(0, d0 * d1)), aa = (b[1] - a[1]) - bb;\n      var nPrep = Math.round(0.1 * FPS), nPouso = Math.round(0.14 * FPS);\n      var nVoo = Math.max(6, Math.round(p.dur * FPS) - nPrep - nPouso);\n      for (i = 0; i < nPrep; i++) empurra(a[0], a[1], 1.14, 0.84);            // pega impulso\n      for (i = 0; i <= nVoo; i++) {\n        var v = i / nVoo;\n        var subindo = v < 0.5;\n        empurra(a[0] + (b[0] - a[0]) * v, aa * v * v + bb * v + a[1],\n          subindo ? 0.9 : 0.95, subindo ? ESTICA : 1.05);\n      }\n      for (i = 0; i < nPouso; i++) {                                           // amassa no pouso\n        var w = i / nPouso;\n        empurra(b[0], b[1], 1.2 - 0.2 * w, 0.8 + 0.2 * w);\n      }\n      ultimo = b;\n    }\n  });\n\n  var DUR = pos.length / FPS;\n  var fCorpo = [], fCorpoPose = [];\n  for (var k = 0; k < pos.length; k++) {\n    var off = k / (pos.length - 1);\n    // os pés ficam em PES da largura; virado para a esquerda, espelha\n    var pes = (pose[k].sx > 0 ? PES : 1 - PES) * larg;\n    fCorpo.push({ offset: off, transform: 'translate(' + ((pos[k].x - pes) * s).toFixed(2) + 'px,' + ((pos[k].y - alt) * s).toFixed(2) + 'px)' });\n    fCorpoPose.push({ offset: off, transform: 'scale(' + pose[k].sx.toFixed(3) + ',' + pose[k].sy.toFixed(3) + ')' });\n  }\n  var opts = { duration: DUR * 1000, delay: ATRASO * 1000, fill: 'both', easing: 'linear' };\n  coelho.animate(fCorpo, opts);\n  corpo.animate(fCorpoPose, opts);\n\n  // Rabinho mexendo enquanto bota o ovo; no meio disso o ovo rosa sai da cesta.\n  setTimeout(function () { coelho.classList.add('botando'); }, (ATRASO + tBota) * 1000);\n  setTimeout(function () { coelho.classList.add('sem-ovo'); }, (ATRASO + tBota + 0.7) * 1000);\n\n  /* ---------- O ovo aparece no pingo do \"i\" quando o coelho sai de cima ---------- */\n  ovo.style.opacity = '';\n  ovo.animate([\n    { offset: 0, opacity: 0, transform: 'scale(.4)' },\n    { offset: 0.35, opacity: 1, transform: 'scale(1.2,.9)' },\n    { offset: 0.55, transform: 'scale(.92,1.08) rotate(-9deg)' },\n    { offset: 0.75, transform: 'scale(1) rotate(6deg)' },\n    { offset: 0.9, transform: 'rotate(-3deg)' },\n    { offset: 1, opacity: 1, transform: 'none' }\n  ], { duration: 700, delay: (ATRASO + tSoltaOvo + 0.12) * 1000, fill: 'both', easing: 'ease-out' });\n\n  setTimeout(function () {\n    var cores = ['#f783ac', '#74c0fc', '#ffffff', '#e64980', '#4a97d4'];\n    var cx = 57.5 * s, cy = 9.5 * s;\n    for (var n = 0; n < 8; n++) {\n      var ang = n / 8 * Math.PI * 2;\n      var b = document.createElement('span');\n      b.className = 'ipc-pascoa-brilho';\n      b.textContent = '✦';\n      b.style.color = cores[n % cores.length];\n      b.style.left = cx + 'px';\n      b.style.top = cy + 'px';\n      b.style.setProperty('--dx', Math.cos(ang) * 14 + 'px');\n      // sem subir muito: o espaço acima do logo é pequeno\n      b.style.setProperty('--dy', Math.sin(ang) * (Math.sin(ang) < 0 ? 4 : 10) + 'px');\n      ancora.appendChild(b);\n      (function (el) { setTimeout(function () { el.remove(); }, 900); })(b);\n    }\n  }, (ATRASO + tSoltaOvo + 0.2) * 1000);\n\n  setTimeout(function () { coelho.remove(); }, (ATRASO + DUR + 0.3) * 1000);\n})();\n","noAr":true,"ordem":1,"pagina":"site-ipc/index.html#pascoa","secao":"Datas comemorativas","secaoOrdem":2,"sistema":"IPC Comercial","tags":["abril","coelho"],"titulo":"Páscoa: coelho e ovo no pingo do i"}$animasys$::jsonb)
