-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio fixo com freio\"></div>\n      <div class=\"product-name\">Rodízio fixo com freio</div>\n      <div class=\"ipc-card-price\"><span>R$ 24,50</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-15%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Roda de gel 75 mm\"></div>\n      <div class=\"product-name\">Roda de gel 75 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 31,00</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n","criadoEm":1790618640000,"css":"/* ---------- 4. Logo: bolinha desce a escada e volta com um super impulso ---------- */\n/* Medidas em % da imagem original (205x90): bolinha em x50 y2, 16px.\n   Nos translate, 100% = diâmetro da bolinha. Degraus: barra 2 (topo y43),\n   barra 1 (topo y66), chão (y88). Roda uma vez por carregamento.\n   A altura dos pulos vem de --ipc-ball-apex / --ipc-ball-hop, calculadas no JS\n   para a bolinha nunca sair da faixa amarela (sem JS: pulo baixo). */\n.logo a.ipc-logo-anim {\n  position: relative;\n}\n.ipc-logo-ball {\n  position: absolute;\n  left: 24.39%;\n  top: 2.22%;\n  width: 7.8%;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  background: #15161a;\n  transform-origin: 50% 100%;\n  pointer-events: none;\n  animation: ipc-ball-escada 2.6s .6s 1 both;\n}\n@keyframes ipc-ball-escada {\n  0%   { transform: translate(0, 0) scale(1);               animation-timing-function: ease-out; }\n  5%   { transform: translate(0, 0) scale(1.18, .82);        animation-timing-function: ease-out; }\n  12%  { transform: translate(-60%, var(--ipc-ball-hop, -10%)) scale(.95, 1.05);  animation-timing-function: ease-in; }\n  21%  { transform: translate(-109%, 156%) scale(1);          animation-timing-function: ease-out; }\n  23%  { transform: translate(-109%, 156%) scale(1.25, .75); animation-timing-function: ease-out; }\n  31%  { transform: translate(-165%, 95%) scale(1);          animation-timing-function: ease-in; }\n  40%  { transform: translate(-216%, 300%) scale(1);          animation-timing-function: ease-out; }\n  42%  { transform: translate(-216%, 300%) scale(1.25, .75); animation-timing-function: ease-out; }\n  50%  { transform: translate(-268%, 235%) scale(1);          animation-timing-function: ease-in; }\n  59%  { transform: translate(-312%, 437%) scale(1);          animation-timing-function: ease-out; }\n  62%  { transform: translate(-312%, 437%) scale(1.3, .7);    animation-timing-function: ease-in-out; }\n  /* carregando o impulso */\n  70%  { transform: translate(-312%, 437%) scale(1.55, .45); animation-timing-function: cubic-bezier(.15, .9, .3, 1); }\n  /* super impulso: estica na subida */\n  76%  { transform: translate(-230%, 60%) scale(.72, 1.45);  animation-timing-function: ease-out; }\n  84%  { transform: translate(-90%, var(--ipc-ball-apex, -10%)) scale(.95, 1.08); animation-timing-function: ease-in; }\n  93%  { transform: translate(0, 0) scale(1.3, .72);          animation-timing-function: ease-out; }\n  97%  { transform: translate(0, calc(var(--ipc-ball-hop, -10%) * .4)) scale(.94, 1.06);      animation-timing-function: ease-in; }\n  100% { transform: translate(0, 0) scale(1); }\n}\n@media (prefers-reduced-motion: reduce) { .ipc-logo-ball { animation: none; } }\n\n/* ===== reveillon ===== */\n/* Tema de Réveillon — IPC Comercial (cópia local)\n * Ativado pela classe body.ipc-reveillon (colocada pelo reveillon.js).\n * Para desligar: ATIVO = false no reveillon.js (ou remova as duas linhas no index.html). */\n\n/* ---------- A bolinha desce a escada e para no chão com o \"pavio aceso\" ---------- */\n/* Mesmos degraus da animação original (100% = diâmetro da bolinha), mas em vez de\n   voltar pulando ela fica tremendo no chão; o JS a transforma no primeiro rojão. */\nbody.ipc-reveillon .ipc-logo-ball {\n  animation: ipc-rv-desce 1.9s .8s 1 both;\n}\n@keyframes ipc-rv-desce {\n  0%   { transform: translate(0, 0) scale(1);                           animation-timing-function: ease-out; }\n  7%   { transform: translate(0, 0) scale(1.18, .82);                    animation-timing-function: ease-out; }\n  16%  { transform: translate(-60%, var(--ipc-ball-hop, -10%)) scale(.95, 1.05); animation-timing-function: ease-in; }\n  28%  { transform: translate(-109%, 156%) scale(1);                     animation-timing-function: ease-out; }\n  31%  { transform: translate(-109%, 156%) scale(1.25, .75);             animation-timing-function: ease-out; }\n  41%  { transform: translate(-165%, 95%) scale(1);                      animation-timing-function: ease-in; }\n  53%  { transform: translate(-216%, 300%) scale(1);                     animation-timing-function: ease-out; }\n  56%  { transform: translate(-216%, 300%) scale(1.25, .75);             animation-timing-function: ease-out; }\n  66%  { transform: translate(-268%, 235%) scale(1);                     animation-timing-function: ease-in; }\n  78%  { transform: translate(-312%, 437%) scale(1);                     animation-timing-function: ease-out; }\n  82%  { transform: translate(-312%, 437%) scale(1.3, .7);               animation-timing-function: ease-in-out; }\n  /* pavio aceso: treme antes de disparar */\n  88%  { transform: translate(-304%, 437%) scale(1.42, .58); }\n  92%  { transform: translate(-320%, 437%) scale(1.45, .55); }\n  96%  { transform: translate(-305%, 437%) scale(1.5, .5); }\n  100% { transform: translate(-312%, 437%) scale(1.5, .5); }\n}\n/* Enquanto ela é o rojão e o show acontece, a bolinha some... */\nbody.ipc-reveillon .ipc-logo-ball.ipc-rv-oculta {\n  visibility: hidden;\n}\n/* ...e volta com um \"pop\" quando o cometa chega no pingo do \"i\". */\nbody.ipc-reveillon .ipc-logo-ball.ipc-rv-volta {\n  transform-origin: 50% 50%;\n  animation: ipc-rv-pop .5s cubic-bezier(.34, 1.56, .64, 1) 1 both;\n}\n@keyframes ipc-rv-pop {\n  0%   { transform: scale(0); }\n  60%  { transform: scale(1.5); }\n  100% { transform: scale(1); }\n}\n\n/* ---------- Céu dos fogos: canvas do tamanho exato da faixa amarela ---------- */\n.ipc-rv-ceu {\n  position: absolute;\n  z-index: 60;\n  pointer-events: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  body.ipc-reveillon .ipc-logo-ball,\n  body.ipc-reveillon .ipc-logo-ball.ipc-rv-volta { animation: none; }\n  .ipc-rv-ceu { display: none; }\n}\n","descricao":"A bolinha desce a escada e vira rojão, o céu ganha fogos, as faíscas formam \"2027\" e um cometa traz a bolinha de volta. Precisa da bolinha do logo (já inclusa aqui).","html":"<a href=\"/\" class=\"ipc-logo-anim\"><img src=\"data:image/png;base64,\" alt=\"IPC Comercial\" title=\"IPC Comercial\"><span class=\"ipc-logo-ball\" aria-hidden=\"true\"></span></a>","js":"/* Bolinha do logo: limita a altura dos pulos ao espaço amarelo acima dela */\n(function fitLogoBall() {\n  var ball = document.querySelector('.ipc-logo-ball');\n  if (!ball) return;\n  var blackBar = document.querySelector('#header-main .header-1');\n  var r = ball.getBoundingClientRect();\n  var d = r.width;\n  if (!d) return;\n  var limit = blackBar ? blackBar.getBoundingClientRect().bottom : r.top - d;\n  var margin = 4;\n  // No ápice a bolinha estica 8% para cima (scale 1.08 com origem embaixo).\n  var room = r.top - limit - margin - d * 0.08;\n  var apex = Math.max(-330, Math.min(0, -room / d * 100));\n  var hop = Math.max(apex, -70);\n  ball.style.setProperty('--ipc-ball-apex', apex.toFixed(1) + '%');\n  ball.style.setProperty('--ipc-ball-hop', hop.toFixed(1) + '%');\n})();\n\n/* ===== reveillon ===== */\n/* Tema de Réveillon — IPC Comercial (cópia local)\n * A bolinha do \"i\" desce a escada do logo e, no chão, vira um rojão: sobe e estoura.\n * Depois sobem mais rojões do pé da faixa amarela, o último forma o ano novo\n * (\"2027\") com as faíscas por cima da busca, e uma faísca volta como cometa até\n * o pingo do \"i\", onde a bolinha reaparece com um \"pop\".\n * Tudo acontece dentro da faixa amarela, uma vez por carregamento.\n * Para desligar: ATIVO = false. */\n(function () {\n  var ATIVO = true;\n  // ?tema=... na URL escolhe o tema (para comparar os temas em abas separadas).\n  var temaUrl = new URLSearchParams(location.search).get('tema');\n  if (temaUrl) ATIVO = temaUrl === 'reveillon';\n  if (!ATIVO) return;\n\n  var ball = document.querySelector('.ipc-logo-ball');\n  var header = document.querySelector('#header-main');\n  if (!ball || !header) return;\n  document.body.classList.add('ipc-reveillon');\n  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;\n\n  // A partir de julho já mostra o ano que vem.\n  var hoje = new Date();\n  var ANO = String(hoje.getMonth() >= 6 ? hoje.getFullYear() + 1 : hoje.getFullYear());\n\n  var CORES = { vermelho: '#e03131', azul: '#1971c2', roxo: '#7048e8', verde: '#2f9e44', laranja: '#e8590c', preto: '#15161a', rosa: '#d6336c' };\n  var black = document.querySelector('#header-main .header-1');\n  var logo = document.querySelector('.logo img');\n  var busca = document.querySelector('.search-field');\n\n  /* ---------- Canvas na faixa amarela (recorta tudo: nada vai para o preto) ---------- */\n  function faixaTela() {\n    var hb = header.getBoundingClientRect();\n    var top = black ? black.getBoundingClientRect().bottom : hb.top;\n    return { left: hb.left, top: top, width: hb.width, height: hb.bottom - top };\n  }\n  var canvas = document.createElement('canvas');\n  canvas.className = 'ipc-rv-ceu';\n  canvas.setAttribute('aria-hidden', 'true');\n  document.body.appendChild(canvas);\n  var ctx = canvas.getContext('2d');\n  var W = 0, H = 0;\n\n  // O cabeçalho ainda muda de posição enquanto a página carrega.\n  function place() {\n    var f = faixaTela();\n    var dpr = Math.min(2, window.devicePixelRatio || 1);\n    canvas.style.left = f.left + window.scrollX + 'px';\n    canvas.style.top = f.top + window.scrollY + 'px';\n    canvas.style.width = f.width + 'px';\n    canvas.style.height = f.height + 'px';\n    if (W !== f.width || H !== f.height) {\n      W = f.width; H = f.height;\n      canvas.width = Math.round(W * dpr);\n      canvas.height = Math.round(H * dpr);\n      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    }\n  }\n  place();\n  var ro = window.ResizeObserver ? new ResizeObserver(place) : null;\n  if (ro) ro.observe(document.body);\n\n  // Retângulo de um elemento em coordenadas da faixa.\n  function naFaixa(el) {\n    var f = faixaTela(), r = el.getBoundingClientRect();\n    return { x: r.left - f.left, y: r.top - f.top, w: r.width, h: r.height, cx: r.left - f.left + r.width / 2, cy: r.top - f.top + r.height / 2 };\n  }\n  // Onde a bolinha fica em repouso (antes de a animação começar ela está no lugar).\n  var repouso = naFaixa(ball);\n\n  /* ---------- Partículas ---------- */\n  var faiscas = [], rojoes = [], letras = [], eventos = [], relogio = 0;\n  function rnd(a, b) { return a + Math.random() * (b - a); }\n  function escolha(l) { return l[Math.floor(Math.random() * l.length)]; }\n  function easeOut(t) { return 1 - Math.pow(1 - t, 3); }\n\n  function faisca(x, y, vx, vy, o) {\n    faiscas.push({\n      x: x, y: y, vx: vx, vy: vy, vida: 0,\n      max: o.vida || 1, cor: o.cor, tam: o.tam || 1.6,\n      arrasto: o.arrasto == null ? 2 : o.arrasto, grav: o.grav == null ? 45 : o.grav,\n      pisca: !!o.pisca\n    });\n  }\n\n  var k = 1;                                   // escala dos estouros pela altura da faixa\n  function estouro(x, y, tipo, cor) {\n    k = Math.max(0.8, Math.min(1.3, H / 95));\n    // clarão rápido no centro\n    faiscas.push({ x: x, y: y, vx: 0, vy: 0, vida: 0, max: 0.18, cor: cor, tam: 0, arrasto: 0, grav: 0, clarao: 11 * k });\n    var n, i, ang, v;\n    if (tipo === 'anel') {\n      n = 36;\n      for (i = 0; i < n; i++) {\n        ang = i / n * Math.PI * 2;\n        faisca(x, y, Math.cos(ang) * 78 * k, Math.sin(ang) * 78 * k, { cor: cor, vida: rnd(1, 1.25), arrasto: 2.6, grav: 30 });\n      }\n    } else if (tipo === 'salgueiro') {\n      n = 40;\n      for (i = 0; i < n; i++) {\n        ang = rnd(0, Math.PI * 2); v = rnd(35, 60) * k;\n        faisca(x, y, Math.cos(ang) * v, Math.sin(ang) * v - 10, { cor: cor, vida: rnd(1.5, 1.9), arrasto: 1.5, grav: 75, tam: 1.4, pisca: true });\n      }\n    } else { // peônia: esfera cheia, com estalinhos no fim\n      n = 48;\n      for (i = 0; i < n; i++) {\n        ang = i / n * Math.PI * 2 + rnd(-0.08, 0.08); v = rnd(58, 90) * k;\n        faisca(x, y, Math.cos(ang) * v, Math.sin(ang) * v, { cor: i % 7 === 0 ? CORES.preto : cor, vida: rnd(1.1, 1.5), arrasto: 2.2, grav: 45, pisca: true });\n      }\n    }\n  }\n\n  // Rojão: sobe numa curva (Bézier) com rastro, e estoura no fim.\n  function rojao(x0, y0, x1, y1, dur, aoChegar) {\n    rojoes.push({\n      x0: x0, y0: y0, x1: x1, y1: y1,\n      cx: x0 + (x1 - x0) * 0.15, cy: Math.max(4, y1 - 6),\n      t: 0, dur: dur, aoChegar: aoChegar, x: x0, y: y0\n    });\n  }\n\n  /* ---------- O ano novo escrito com as faíscas ---------- */\n  function pontosDoTexto(texto, cx, cy, altura) {\n    var off = document.createElement('canvas');\n    var fs = Math.round(altura);\n    var c2 = off.getContext('2d');\n    c2.font = '800 ' + fs + 'px Poppins, sans-serif';\n    var larg = Math.ceil(c2.measureText(texto).width) + 4;\n    off.width = larg; off.height = fs + 8;\n    c2.font = '800 ' + fs + 'px Poppins, sans-serif';\n    c2.textBaseline = 'middle';\n    c2.fillText(texto, 2, off.height / 2);\n    var d = c2.getImageData(0, 0, off.width, off.height).data, pts = [];\n    var passo = Math.max(2, Math.round(fs / 17));\n    for (var y = 0; y < off.height; y += passo)\n      for (var x = 0; x < off.width; x += passo)\n        if (d[(y * off.width + x) * 4 + 3] > 140) pts.push({ x: cx - larg / 2 + x, y: cy - off.height / 2 + y });\n    return { pts: pts, larg: larg };\n  }\n\n  var textoInfo = null;\n  function formarAno(x, y, alvo) {\n    faiscas.push({ x: x, y: y, vx: 0, vy: 0, vida: 0, max: 0.25, cor: CORES.rosa, tam: 0, arrasto: 0, grav: 0, clarao: 16 * k });\n    var alt = Math.min(H * 0.5, alvo.h ? alvo.h * 0.9 : H * 0.45);\n    textoInfo = pontosDoTexto(ANO, alvo.cx, alvo.cy, alt);\n    textoInfo.cx = alvo.cx; textoInfo.cy = alvo.cy;\n    textoInfo.pts.forEach(function (p, i) {\n      letras.push({ sx: x, sy: y, tx: p.x, ty: p.y, x: x, y: y, t: 0, atraso: rnd(0, 0.12), cor: i % 4 === 0 ? CORES.vermelho : CORES.preto, fase: rnd(0, 6.28) });\n    });\n  }\n  function soltarAno() {\n    letras.forEach(function (l) {\n      faisca(l.x, l.y, rnd(-18, 18), rnd(-14, 6), { cor: l.cor, vida: rnd(0.7, 1.1), arrasto: 1, grav: 70, tam: 1.3, pisca: true });\n    });\n    letras = [];\n  }\n\n  /* ---------- A bolinha volta: cometa até o pingo do \"i\" ---------- */\n  function cometa(x0, y0) {\n    var alvo = { x: repouso.cx, y: repouso.cy };\n    var c = { x: (x0 + alvo.x) / 2, y: Math.max(5, Math.min(y0, alvo.y) - 18) };\n    rojoes.push({ x0: x0, y0: y0, x1: alvo.x, y1: alvo.y, cx: c.x, cy: c.y, t: 0, dur: 0.75, cometa: true, x: x0, y: y0, aoChegar: function () {\n      ball.classList.remove('ipc-rv-oculta');\n      ball.classList.add('ipc-rv-volta');\n      for (var i = 0; i < 14; i++) {\n        var ang = i / 14 * Math.PI * 2;\n        faisca(alvo.x, alvo.y, Math.cos(ang) * 40, Math.sin(ang) * 40, { cor: i % 2 ? CORES.vermelho : CORES.preto, vida: 0.5, arrasto: 3, grav: 20, tam: 1.3 });\n      }\n    } });\n  }\n\n  /* ---------- Roteiro do show (tempos em s a partir do dis