class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n<!--ANIMACAO-->","criadoEm":1790618880000,"css":"/* ---------- 3. Produto adicionado à sacola ---------- */\n.ipc-fly-img {\n  position: fixed;\n  z-index: 100000;\n  pointer-events: none;\n  object-fit: contain;\n  border-radius: 50%;\n  background: #fff;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, .25);\n}\n\n.link-shopping-cart.ipc-cart-bump .icon-shopping-cart {\n  animation: ipc-cart-bump .6s cubic-bezier(.34, 1.56, .64, 1);\n}\n.ipc-count-pop {\n  display: inline-block;\n  animation: ipc-count-pop .5s ease;\n}\n@keyframes ipc-cart-bump {\n  0%   { transform: scale(1) rotate(0); }\n  30%  { transform: scale(1.35) rotate(-10deg); }\n  60%  { transform: scale(.9) rotate(6deg); }\n  100% { transform: scale(1) rotate(0); }\n}\n@keyframes ipc-count-pop {\n  0%   { transform: scale(1); }\n  40%  { transform: scale(1.8); color: #1e7f3c; }\n  100% { transform: scale(1); }\n}\n\n.btn-buy-kit.ipc-added {\n  background: #1e7f3c !important;\n  border-color: #1e7f3c !important;\n  color: #fff !important;\n  transition: background .25s ease;\n}","descricao":"Clique em \"Comprar\": a foto do produto voa até a sacola, o ícone pula, o contador e o total sobem e o botão fica verde \"Adicionado ✓\". É só visual.","html":"","js":"/* Produto voando para a sacola (clique em \"Comprar\") */\n(function () {\n  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function parsePrice(text) {\n    var m = /R\\$\\s*([\\d.]+,\\d{2})/.exec(text || '');\n    return m ? parseFloat(m[1].replace(/\\./g, '').replace(',', '.')) : 0;\n  }\n\n  function formatPrice(v) {\n    return 'R$ ' + v.toFixed(2).replace('.', ',').replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.');\n  }\n\n  function visibleCartIcon() {\n    var icons = document.querySelectorAll('.link-shopping-cart .icon-shopping-cart');\n    for (var i = 0; i < icons.length; i++) {\n      var r = icons[i].getBoundingClientRect();\n      if (r.width && r.height) return icons[i];\n    }\n    return icons[0];\n  }\n\n  function flyToCart(img, done) {\n    var target = visibleCartIcon();\n    if (!img || !target || reduceMotion) return done();\n\n    var from = img.getBoundingClientRect();\n    var to = target.getBoundingClientRect();\n    var clone = img.cloneNode();\n    clone.removeAttribute('srcset');\n    clone.className = 'ipc-fly-img';\n    var size = Math.min(from.width, from.height, 140);\n    clone.style.width = size + 'px';\n    clone.style.height = size + 'px';\n    clone.style.left = from.left + (from.width - size) / 2 + 'px';\n    clone.style.top = from.top + (from.height - size) / 2 + 'px';\n    document.body.appendChild(clone);\n\n    var dx = to.left + to.width / 2 - (parseFloat(clone.style.left) + size / 2);\n    var dy = to.top + to.height / 2 - (parseFloat(clone.style.top) + size / 2);\n\n    var anim = clone.animate([\n      { transform: 'translate(0,0) scale(1)', opacity: 1 },\n      { transform: 'translate(' + dx * 0.5 + 'px,' + (dy * 0.5 - 120) + 'px) scale(.6)', opacity: 1, offset: 0.5 },\n      { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(.12)', opacity: .6 }\n    ], { duration: 800, easing: 'cubic-bezier(.45,0,.25,1)' });\n\n    // Fallback timer: onfinish never fires if the tab is hidden mid-animation.\n    var finished = false;\n    function finish() {\n      if (finished) return;\n      finished = true;\n      clone.remove();\n      done();\n    }\n    anim.onfinish = finish;\n    setTimeout(finish, 900);\n  }\n\n  function bumpCart(price) {\n    document.querySelectorAll('.link-shopping-cart').forEach(function (cart) {\n      cart.classList.remove('ipc-cart-bump');\n      void cart.offsetWidth;\n      cart.classList.add('ipc-cart-bump');\n    });\n    document.querySelectorAll('.shopping-cart-total-products').forEach(function (el) {\n      el.textContent = (parseInt(el.textContent, 10) || 0) + 1;\n      el.classList.remove('ipc-count-pop');\n      void el.offsetWidth;\n      el.classList.add('ipc-count-pop');\n    });\n    document.querySelectorAll('.shopping-cart-total-price').forEach(function (el) {\n      el.textContent = formatPrice(parsePrice(el.textContent) + price);\n    });\n  }\n\n\n  // Capture phase so the site's own handlers and the link navigation don't run.\n  document.addEventListener('click', function (e) {\n    var btn = e.target.closest && e.target.closest('.btn-buy-kit');\n    if (!btn) return;\n    e.preventDefault();\n    e.stopImmediatePropagation();\n\n    var card = btn.closest('.product-list-item-inner') || btn.parentElement;\n    var img = card.querySelector('.product-image img');\n    var nameEl = card.querySelector('.product-name');\n    var name = nameEl ? nameEl.textContent.trim() : '';\n    var priceEl = card.querySelector('.ipc-card-price') || card.querySelector('[class*=price]');\n    var price = parsePrice(priceEl ? priceEl.textContent : '');\n\n    var label = btn.querySelector('.btn-text');\n    btn.classList.add('ipc-added');\n    if (label) label.textContent = 'Adicionado ✓';\n    setTimeout(function () {\n      btn.classList.remove('ipc-added');\n      if (label) label.textContent = 'Comprar';\n    }, 1800);\n\n    flyToCart(img, function () {\n      bumpCart(price);\n    });\n  }, true);\n})();","noAr":true,"ordem":3,"pagina":"site-ipc/index.html#nenhum","secao":"Loja","secaoOrdem":3,"sistema":"IPC Comercial","tags":["clique","contador"],"titulo":"Produto voando para a sacola"}$animasys$::jsonb)
