 </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Rodízio fixo com freio\"></div>\n      <div class=\"product-name\">Rodízio fixo com freio</div>\n      <div class=\"ipc-card-price\"><span>R$ 24,50</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      <span class=\"label-promo\">-15%</span>\n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Roda de gel 75 mm\"></div>\n      <div class=\"product-name\">Roda de gel 75 mm</div>\n      <div class=\"ipc-card-price\"><span>R$ 31,00</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n    <li class=\"product-list-item\"><div class=\"product-list-item-inner\">\n      \n      <div class=\"product-image\"><img src=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%20120%22%3E%3Crect%20width%3D%22120%22%20height%3D%22120%22%20rx%3D%2210%22%20fill%3D%22%23f1f1f1%22%2F%3E%3Cpath%20d%3D%22M40%2018h40v14H40z%22%20fill%3D%22%239aa0a6%22%2F%3E%3Cpath%20d%3D%22M58%2032h4v14h-4z%22%20fill%3D%22%236b7178%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2230%22%20fill%3D%22%232b2f33%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%2214%22%20fill%3D%22%23c9ced3%22%2F%3E%3Ccircle%20cx%3D%2260%22%20cy%3D%2274%22%20r%3D%225%22%20fill%3D%22%236b7178%22%2F%3E%3C%2Fsvg%3E\" alt=\"Esfera transferidora\"></div>\n      <div class=\"product-name\">Esfera transferidora</div>\n      <div class=\"ipc-card-price\"><span>R$ 12,40</span></div>\n      <a class=\"btn-buy-kit\" href=\"#\"><span class=\"btn-text\">Comprar</span></a>\n    </div></li>\n</ul>\n<!--ANIMACAO-->","criadoEm":1790618760000,"css":"/* ---------- 1. Botão do WhatsApp: só o logo, expande no hover ---------- */\n.wa-chat-wrapper .wa-chat-header {\n  width: auto !important;\n  padding: 12px !important;\n  border-radius: 999px !important;\n  box-shadow: 0 6px 18px rgba(0, 0, 0, .22);\n  transition: box-shadow .3s ease, transform .3s ease;\n  animation: ipc-wa-pulse 2.4s ease-out infinite;\n}\n.wa-chat-wrapper .wa-chat-header a {\n  display: flex !important;\n  align-items: center;\n  text-decoration: none;\n}\n.wa-chat-wrapper .wa-chat-icon {\n  flex: 0 0 auto;\n  transition: transform .35s ease;\n}\n.wa-chat-wrapper .wa-chat-title {\n  display: inline-block;\n  max-width: 0;\n  margin: 0 !important;\n  opacity: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  vertical-align: middle;\n  transition: max-width .4s ease, margin-left .4s ease, opacity .25s ease;\n}\n.wa-chat-wrapper .wa-chat-header:hover {\n  animation: none;\n  transform: translateY(-2px);\n  box-shadow: 0 10px 24px rgba(0, 0, 0, .28);\n}\n.wa-chat-wrapper .wa-chat-header:hover .wa-chat-title {\n  max-width: 120px;\n  margin: 0 6px 0 10px !important;\n  opacity: 1;\n  transition: max-width .4s ease, margin-left .4s ease, opacity .3s ease .1s;\n}\n.wa-chat-wrapper .wa-chat-header:hover .wa-chat-icon {\n  transform: rotate(-12deg);\n}\n@keyframes ipc-wa-pulse {\n  0%   { box-shadow: 0 6px 18px rgba(0,0,0,.22), 0 0 0 0 rgba(87, 187, 99, .55); }\n  70%  { box-shadow: 0 6px 18px rgba(0,0,0,.22), 0 0 0 14px rgba(87, 187, 99, 0); }\n  100% { box-shadow: 0 6px 18px rgba(0,0,0,.22), 0 0 0 0 rgba(87, 187, 99, 0); }\n}\n@media (prefers-reduced-motion: reduce) { .wa-chat-wrapper .wa-chat-header { animation: none; } }","descricao":"O botão vira só o ícone num círculo verde que pulsa. Ao passar o mouse ele abre e mostra \"WhatsApp\".","html":"<div class=\"wa-chat-wrapper wa-chat-right\">\n  <div class=\"wa-chat-header\" style=\"background: #57bb63\">\n    <a target=\"_blank\" href=\"https://api.whatsapp.com/send?phone=551131361560\">\n      <span class=\"wa-chat-icon\"></span>\n      <span class=\"wa-chat-title\">WhatsApp</span>\n    </a>\n  </div>\n</div>","js":"","noAr":true,"ordem":1,"pagina":"site-ipc/index.html#nenhum","secao":"Loja","secaoOrdem":3,"sistema":"IPC Comercial","tags":["botão","pulso"],"titulo":"Botão do WhatsApp pulsando"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
insert into public.animacoes (id, dados) values ('mr-coluna-batimento', $animasys${"atualizadoEm":1790619060000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #f4f3f0; }\nbody { display: grid; place-items: center; }\n.recursos { width: min(520px, calc(100vw - 32px)); } /* largura fixa: não depende do texto */\n.wrap { padding: 0; }\n.recursos-grid { display: block !important; }","baseHtml":"","criadoEm":1790619060000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* ---------- recursos ---------- */\n.recursos-grid { display: grid; gap: 40px; padding-top: 64px; padding-bottom: 64px; }\n@media (min-width: 768px) { .recursos-grid { grid-template-columns: repeat(3, 1fr); gap: 48px; padding-top: 96px; padding-bottom: 96px; } }\n.rec { border-top: 1px solid rgba(20, 20, 22, .15); padding-top: 24px; }\n.rec .num { margin: 0; font-size: 14px; font-weight: 500; color: var(--coral-escuro); font-variant-numeric: tabular-nums; }\n.rec h2 { margin: 12px 0 0; font-family: var(--marca); font-size: 28px; font-weight: 600; letter-spacing: -.015em; }\n.rec p:last-child { margin: 8px 0 0; font-size: 16px; line-height: 1.6; color: var(--noite-medio); }\n\n/* trilho: a linha do topo de cada coluna vira um trecho de rota */\n.rec { position: relative; }\n.rec h2 { transform-origin: left center; }\n.trilho { position: absolute; left: 0; right: 0; top: -1px; height: 1px; pointer-events: none; }\n.trilho .linha { position: absolute; inset: 0; background: var(--coral); transform-origin: left; transform: scaleX(0); }\n.trilho .ponta {\n  position: absolute; top: -3.5px; left: 0; width: 8px; height: 8px; margin-left: -4px;\n  border-radius: 50%; background: var(--coral); box-shadow: 0 0 0 4px rgba(255, 99, 79, .18); opacity: 0;\n}\n.trilho .ecg { position: absolute; left: 0; top: -19.5px; width: 100%; height: 40px; overflow: visible; visibility: hidden; }\n.trilho .ecg path { fill: none; stroke: var(--coral); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }\n.trilho .ecg.vivo { filter: drop-shadow(0 0 3px rgba(255, 99, 79, .55)); }\n.trilho .onda {\n  position: absolute; left: 0; top: -5px; width: 10px; height: 10px; margin-left: -5px;\n  border: 1.5px solid var(--coral); border-radius: 50%; opacity: 0; box-sizing: border-box;\n}\n.rec[data-anim=\"pulsar\"] .ponta { z-index: 1; }\n.trilho .ok {\n  position: absolute; right: -8px; top: -8px; width: 16px; height: 16px; border-radius: 50%;\n  background: var(--verde); display: grid; place-items: center; transform: scale(0);\n}\n.trilho .ok svg { width: 10px; height: 10px; }\n\n/* estado inicial (só com JS ativo) */\n.rec-js .rec .num, .rec-js .rec h2, .rec-js .rec > p:last-child { opacity: 0; }\n/* estado final sem animação (reduzir movimento / modo edição) */\n.rec-final .trilho .linha { transform: none; }\n.rec-final .trilho .ok { transform: none; }","descricao":"A linha vira um monitor: o ponto corre sobre o traçado, cada pico solta uma onda e faz o título pulsar (tum-tum). No fim o eletro acalma e vira linha reta. Roda quando a seção aparece na tela.","html":"<section class=\"recursos\" id=\"recursos\">\n  <div class=\"wrap recursos-grid\">\n    <div class=\"rec\" data-anim=\"pulsar\"><p class=\"num\">02</p><h2>Reviva</h2><p>Ritmo e batimentos saem do seu próprio histórico.</p></div>\n  </div>\n</section>","js":"(function () {\n  var params = new URLSearchParams(location.search);\n  var SPEED = parseFloat(params.get('speed')) || 1;\n  var REDUZIR = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* ---------- recursos: um ponto percorre 01 → 02 → 03 ---------- */\n  var secao = document.querySelector('.recursos');\n  var recs = [].slice.call(secao.querySelectorAll('.rec'));\n  recs.forEach(function (rec) {\n    var t = document.createElement('div');\n    t.className = 'trilho'; t.setAttribute('aria-hidden', 'true');\n    t.innerHTML = '<i class=\"linha\"></i><i class=\"ponta\"></i>';\n    if (rec.dataset.anim === 'pulsar')\n      t.insertAdjacentHTML('beforeend', '<svg class=\"ecg\"><path/></svg><i class=\"onda\"></i>');\n    if (rec.dataset.anim === 'recuperar')\n      t.insertAdjacentHTML('beforeend', '<span class=\"ok\"><svg viewBox=\"0 0 16 16\"><path d=\"M3.8 8.4l2.6 2.6 5.6-6\" fill=\"none\" stroke=\"#141416\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>');\n    rec.insertBefore(t, rec.firstChild);\n  });\n\n  var tempo = function (ms) { return ms / SPEED; };\n  function A(el, kf, opt) {\n    opt = Object.assign({ fill: 'forwards' }, opt);\n    opt.duration = tempo(opt.duration); if (opt.delay) opt.delay = tempo(opt.delay);\n    return el.animate(kf, opt).finished;\n  }\n  var SOBE = [{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }];\n  var SAIDA = 'cubic-bezier(.2,.8,.2,1)', VAIVEM = 'cubic-bezier(.65,0,.35,1)';\n  var TITULO = 120, TEXTO = 550; // mesmo atraso de título e texto nas 3 colunas\n  var DURACAO = 1200;            // mesma duração da linha nas 3 colunas\n  function partes(rec) {\n    return { linha: rec.querySelector('.linha'), ponta: rec.querySelector('.ponta'), num: rec.querySelector('.num'),\n             h2: rec.querySelector('h2'), p: rec.querySelector('p:last-child') };\n  }\n\n  // 02 — batimento: a linha vira um monitor cardíaco. O ponto corre SOBRE o traçado (sobe e desce nos picos),\n  // cada pico solta uma onda e faz o título pulsar (tum-tum). No fim o eletro \"acalma\" e vira a linha reta.\n  function pulsar(rec) {\n    var e = partes(rec), ecg = rec.querySelector('.ecg'), path = ecg.querySelector('path'), onda = rec.querySelector('.onda');\n    var L = Math.round(rec.getBoundingClientRect().width), Y = 20, D = DURACAO;\n    var picos = [Math.round(L * .34), Math.round(L * .68)];\n    // cada batida ocupa 92px; em colunas estreitas ela encolhe para sobrar folga entre as duas\n    var sx = Math.max(.45, Math.min(1, (L * .34 - 28) / 92));\n\n    // uma batida PQRST com amplitude a (0 = linha reta)\n    function batida(c, a) {\n      var x = function (dx) { return (c + dx * sx).toFixed(1); };\n      return 'H' + x(-46) +\n        'C' + x(-42) + ' ' + Y + ' ' + x(-40) + ' ' + (Y - 4 * a) + ' ' + x(-35) + ' ' + (Y - 4 * a) +      // P\n        'C' + x(-30) + ' ' + (Y - 4 * a) + ' ' + x(-28) + ' ' + Y + ' ' + x(-24) + ' ' + Y +\n        'H' + x(-8) + 'L' + x(-4) + ' ' + (Y + 4 * a) + 'L' + c + ' ' + (Y - 17 * a) +                   // Q R\n        'L' + x(5) + ' ' + (Y + 8 * a) + 'L' + x(9) + ' ' + Y +                                          // S\n        'H' + x(18) + 'C' + x(23) + ' ' + Y + ' ' + x(26) + ' ' + (Y - 6 * a) + ' ' + x(32) + ' ' + (Y - 6 * a) + // T\n        'C' + x(38) + ' ' + (Y - 6 * a) + ' ' + x(41) + ' ' + Y + ' ' + x(46) + ' ' + Y;\n    }\n    function traco(a) { return 'M0 ' + Y + batida(picos[0], a) + batida(picos[1], a) + 'H' + L; }\n\n    ecg.setAttribute('viewBox', '0 0 ' + L + ' 40');\n    path.setAttribute('d', traco(1));\n    var total = path.getTotalLength();\n    // tabela x → comprimento, para o ponto e o traço andarem juntos no eixo x\n    var tab = [], N = Math.max(200, Math.round(total / 2));\n    for (var i = 0; i <= N; i++) { var q = path.getPointAtLength(total * i / N); tab.push([q.x, q.y, total * i / N]); }\n    function noX(x) { var lo = 0, hi = N; while (lo < hi) { var m = (lo + hi) >> 1; tab[m][0] < x ? lo = m + 1 : hi = m; } return tab[lo]; }\n\n    path.style.strokeDasharray = total + ' ' + total;\n    path.style.strokeDashoffset = total;\n    ecg.classList.add('vivo');\n    ecg.style.visibility = 'visible';\n\n    // número: lê \"dados\" e desacelera até assentar na primeira batida\n    var alvo = e.num.textContent, passo = 40, fim = false;\n    e.num.style.opacity = 1; e.num.style.fontVariantNumeric = 'tabular-nums';\n    (function sorteia() {\n      if (fim) { e.num.textContent = alvo; return; }\n      e.num.textContent = ('0' + Math.floor(Math.random() * 100)).slice(-2);\n      passo *= 1.12; setTimeout(sorteia, tempo(passo));\n    })();\n\n    A(e.h2, SOBE, { duration: 500, delay: TITULO, easing: SAIDA });\n    A(e.p, SOBE, { duration: 650, delay: TEXTO, easing: SAIDA });\n    var tumTum = [{ transform: 'scale(1)' }, { transform: 'scale(1.06)', offset: .14 }, { transform: 'scale(.995)', offset: .38 },\n                  { transform: 'scale(1.025)', offset: .52 }, { transform: 'scale(1)' }];\n\n    function bate(k, x, y) {\n      A(e.h2, tumTum, { duration: 520, easing: 'ease-out', composite: 'add' });\n      A(e.ponta, [{ boxShadow: '0 0 0 4px rgba(255,99,79,.18)' }, { boxShadow: '0 0 0 9px rgba(255,99,79,0)' }], { duration: 500, fill: 'none' });\n      var o = onda.cloneNode(); onda.parentNode.appendChild(o);\n      A(o, [{ opacity: .9, transform: 'translate(' + x + 'px,' + y + 'px) scale(.4)' }, { opacity: 0, transform: 'translate(' + x + 'px,' + y + 'px) scale(3.4)' }],\n        { duration: 1000, easing: 'cubic-bezier(.1,.7,.3,1)' }).then(function () { o.remove(); });\n      if (k === 0) fim = true;\n    }\n\n    var suaveSeno = function (t) { return -(Math.cos(Math.PI * t) - 1) / 2; };\n    var batidas = 0;\n    e.ponta.style.left = '0px';\n    A(e.ponta, [{ opacity: 0 }, { opacity: 1 }], { duration: 200 });\n\n    return new Promise(function (pronto) {\n      var t0 = performance.now();\n      (function quadro(t) {\n        var p = Math.min(1, (t - t0) * SPEED / D), x = L * suaveSeno(p), pt = noX(x);\n        path.style.strokeDashoffset = total - pt[2];\n        e.ponta.style.transform = 'translate(' + pt[0].toFixed(1) + 'px,' + (pt[1] - Y).toFixed(1) + 'px)';\n        while (batidas < picos.length && x >= picos[batidas]) { bate(batidas, picos[batidas], -17); batidas++; }\n        if (p < 1) return requestAnimationFrame(quadro);\n        pronto();\n      })(t0);\n    }).then(function () {\n      // o monitor acalma: amplitude 1 → 0, e a linha reta assume.\n      // Roda em paralelo: a próxima coluna já começa quando o ponto chega ao fim.\n      A(e.ponta, [{ opacity: 1 }, { opacity: 0 }], { duration: 300 });\n      path.style.strokeDasharray = 'none';\n      e.linha.style.transform = 'none'; // a linha reta já fica por baixo, sem troca brusca no fim\n      var t0 = performance.now(), DUR = tempo(800);\n      (function quadro(t) {\n        var p = Math.min(1, (t - t0) / DUR), a = Math.pow(1 - p, 3);\n        path.setAttribute('d', traco(a));\n        ecg.style.opacity = 1 - p * p; // brilho e espessura somem junto com os picos\n        if (p < 1) return requestAnimationFrame(quadro);\n        ecg.classList.remove('vivo');\n        ecg.style.visibility = 'hidden';\n      })(t0);\n    });\n  }\n\n  var ANIMS = { pulsar: pulsar };\n  if (REDUZIR || params.has('editar') || !Element.prototype.animate || !('IntersectionObserver' in window)) {\n    secao.classList.add('rec-final');\n  } else {\n    secao.classList.add('rec-js');\n    var io = new IntersectionObserver(function (es) {\n      if (!es[0].isIntersecting) return;\n      io.disconnect();\n      (document.fonts ? document.fonts.ready : Promise.resolve()).then(function () {\n        recs.forEach(function (rec) { ANIMS[rec.dataset.anim](rec); });\n      });\n    }, { threshold: .35 });\n    io.observe(secao);\n  }\n})();","noAr":true,"ordem":4,"pagina":"myrunning/index.html#recursos","secao":"Página inicial","secaoOrdem":1,"sistema":"myrunn.ing","tags":["linha","batimento"],"titulo":"Linha com batimento cardíaco"}$animasys$::jsonb)
