insert into public.animacoes (id, dados) values ('mr-coluna-tracar', $animasys${"atualizadoEm":1790619000000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #f4f3f0; }\nbody { display: grid; place-items: center; }\n.recursos { width: min(520px, calc(100vw - 32px)); } /* largura fixa: não depende do texto */\n.wrap { padding: 0; }\n.recursos-grid { display: block !important; }","baseHtml":"","criadoEm":1790619000000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* ---------- recursos ---------- */\n.recursos-grid { display: grid; gap: 40px; padding-top: 64px; padding-bottom: 64px; }\n@media (min-width: 768px) { .recursos-grid { grid-template-columns: repeat(3, 1fr); gap: 48px; padding-top: 96px; padding-bottom: 96px; } }\n.rec { border-top: 1px solid rgba(20, 20, 22, .15); padding-top: 24px; }\n.rec .num { margin: 0; font-size: 14px; font-weight: 500; color: var(--coral-escuro); font-variant-numeric: tabular-nums; }\n.rec h2 { margin: 12px 0 0; font-family: var(--marca); font-size: 28px; font-weight: 600; letter-spacing: -.015em; }\n.rec p:last-child { margin: 8px 0 0; font-size: 16px; line-height: 1.6; color: var(--noite-medio); }\n\n/* trilho: a linha do topo de cada coluna vira um trecho de rota */\n.rec { position: relative; }\n.rec h2 { transform-origin: left center; }\n.trilho { position: absolute; left: 0; right: 0; top: -1px; height: 1px; pointer-events: none; }\n.trilho .linha { position: absolute; inset: 0; background: var(--coral); transform-origin: left; transform: scaleX(0); }\n.trilho .ponta {\n  position: absolute; top: -3.5px; left: 0; width: 8px; height: 8px; margin-left: -4px;\n  border-radius: 50%; background: var(--coral); box-shadow: 0 0 0 4px rgba(255, 99, 79, .18); opacity: 0;\n}\n.trilho .ecg { position: absolute; left: 0; top: -19.5px; width: 100%; height: 40px; overflow: visible; visibility: hidden; }\n.trilho .ecg path { fill: none; stroke: var(--coral); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }\n.trilho .ecg.vivo { filter: drop-shadow(0 0 3px rgba(255, 99, 79, .55)); }\n.trilho .onda {\n  position: absolute; left: 0; top: -5px; width: 10px; height: 10px; margin-left: -5px;\n  border: 1.5px solid var(--coral); border-radius: 50%; opacity: 0; box-sizing: border-box;\n}\n.rec[data-anim=\"pulsar\"] .ponta { z-index: 1; }\n.trilho .ok {\n  position: absolute; right: -8px; top: -8px; width: 16px; height: 16px; border-radius: 50%;\n  background: var(--verde); display: grid; place-items: center; transform: scale(0);\n}\n.trilho .ok svg { width: 10px; height: 10px; }\n\n/* estado inicial (só com JS ativo) */\n.rec-js .rec .num, .rec-js .rec h2, .rec-js .rec > p:last-child { opacity: 0; }\n/* estado final sem animação (reduzir movimento / modo edição) */\n.rec-final .trilho .linha { transform: none; }\n.rec-final .trilho .ok { transform: none; }","descricao":"Um ponto coral percorre a linha do topo e o título vai sendo \"desenhado\" junto, da esquerda para a direita. Depois o texto sobe. Roda quando a seção aparece na tela.","html":"<section class=\"recursos\" id=\"recursos\">\n  <div class=\"wrap recursos-grid\">\n    <div class=\"rec\" data-anim=\"tracar\"><p class=\"num\">01</p><h2>Redesenhe</h2><p>Mostre no mapa por onde você passou e o traçado aparece.</p></div>\n  </div>\n</section>","js":"(function () {\n  var params = new URLSearchParams(location.search);\n  var SPEED = parseFloat(params.get('speed')) || 1;\n  var REDUZIR = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* ---------- recursos: um ponto percorre 01 → 02 → 03 ---------- */\n  var secao = document.querySelector('.recursos');\n  var recs = [].slice.call(secao.querySelectorAll('.rec'));\n  recs.forEach(function (rec) {\n    var t = document.createElement('div');\n    t.className = 'trilho'; t.setAttribute('aria-hidden', 'true');\n    t.innerHTML = '<i class=\"linha\"></i><i class=\"ponta\"></i>';\n    if (rec.dataset.anim === 'pulsar')\n      t.insertAdjacentHTML('beforeend', '<svg class=\"ecg\"><path/></svg><i class=\"onda\"></i>');\n    if (rec.dataset.anim === 'recuperar')\n      t.insertAdjacentHTML('beforeend', '<span class=\"ok\"><svg viewBox=\"0 0 16 16\"><path d=\"M3.8 8.4l2.6 2.6 5.6-6\" fill=\"none\" stroke=\"#141416\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>');\n    rec.insertBefore(t, rec.firstChild);\n  });\n\n  var tempo = function (ms) { return ms / SPEED; };\n  function A(el, kf, opt) {\n    opt = Object.assign({ fill: 'forwards' }, opt);\n    opt.duration = tempo(opt.duration); if (opt.delay) opt.delay = tempo(opt.delay);\n    return el.animate(kf, opt).finished;\n  }\n  var SOBE = [{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }];\n  var SAIDA = 'cubic-bezier(.2,.8,.2,1)', VAIVEM = 'cubic-bezier(.65,0,.35,1)';\n  var TITULO = 120, TEXTO = 550; // mesmo atraso de título e texto nas 3 colunas\n  var DURACAO = 1200;            // mesma duração da linha nas 3 colunas\n  function partes(rec) {\n    return { linha: rec.querySelector('.linha'), ponta: rec.querySelector('.ponta'), num: rec.querySelector('.num'),\n             h2: rec.querySelector('h2'), p: rec.querySelector('p:last-child') };\n  }\n\n  // 01 — o título é \"desenhado\" junto com a linha, da esquerda para a direita\n  function tracar(rec) {\n    var e = partes(rec), D = DURACAO;\n    A(e.num, SOBE, { duration: 400, easing: SAIDA });\n    A(e.ponta, [{ opacity: 0, left: '0%' }, { opacity: 1, left: '0%', offset: .06 }, { opacity: 1, left: '100%' }], { duration: D, easing: VAIVEM });\n    A(e.h2, [{ opacity: 1, clipPath: 'inset(-20% 100% -20% 0)' }, { opacity: 1, clipPath: 'inset(-20% 0% -20% 0)' }], { duration: D * .85, delay: TITULO, easing: VAIVEM });\n    A(e.p, SOBE, { duration: 650, delay: TEXTO, easing: SAIDA });\n    return A(e.linha, [{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], { duration: D, easing: VAIVEM })\n      .then(function () { A(e.ponta, [{ opacity: 1 }, { opacity: 0 }], { duration: 300 }); });\n  }\n\n  var ANIMS = { tracar: tracar };\n  if (REDUZIR || params.has('editar') || !Element.prototype.animate || !('IntersectionObserver' in window)) {\n    secao.classList.add('rec-final');\n  } else {\n    secao.classList.add('rec-js');\n    var io = new IntersectionObserver(function (es) {\n      if (!es[0].isIntersecting) return;\n      io.disconnect();\n      (document.fonts ? document.fonts.ready : Promise.resolve()).then(function () {\n        recs.forEach(function (rec) { ANIMS[rec.dataset.anim](rec); });\n      });\n    }, { threshold: .35 });\n    io.observe(secao);\n  }\n})();","noAr":true,"ordem":3,"pagina":"myrunning/index.html#recursos","secao":"Página inicial","secaoOrdem":1,"sistema":"myrunn.ing","tags":["linha","título"],"titulo":"Linha que se traça com o título"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
insert into public.animacoes (id, dados) values ('mr-entrada-titulo', $animasys${"atualizadoEm":1790619300000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #141416; }\nbody { color: #f4f3f0; display: grid; place-items: center; padding: 24px; }\n.texto { max-width: 560px; }\n.sobre { margin: 0; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .14em; color: rgba(255, 255, 255, .55); }\nh1 {\n  margin: 16px 0 0;\n  font-family: var(--marca); font-weight: 600;\n  font-size: 2.75rem; line-height: 1; letter-spacing: -.03em;\n}\n@media (min-width: 640px) { h1 { font-size: 4.5rem; } }\nh1 .h1-b { color: var(--coral); }\n\n/* modo ?editar */\nbody.editando [data-texto] { outline: 1px dashed rgba(255, 99, 79, .6); outline-offset: 3px; cursor: text; }\nbody.editando [data-texto]:focus { outline: 2px solid var(--coral); }\n.aviso-editar {\n  position: fixed; left: 16px; bottom: 16px; z-index: 50;\n  font: 600 13px var(--sans); color: #fff; background: var(--noite);\n  border: 1px solid rgba(255, 255, 255, .15); border-radius: 12px; padding: 10px 14px;\n}\n.aviso-editar button { font: inherit; color: var(--coral); background: none; border: 0; cursor: pointer; padding: 0 0 0 10px; }\n.lead { margin: 24px 0 0; max-width: 44ch; font-size: 18px; line-height: 1.6; color: rgba(255, 255, 255, .7); }\n.acoes { margin-top: 32px; display: flex; flex-wrap: wrap; gap: 12px; }\n.btn {\n  font: 700 16px var(--sans); cursor: pointer;\n  display: inline-flex; align-items: center; height: 48px;\n  padding: 0 28px; border-radius: 16px; background: none; color: #fff;\n  transition: transform .15s, background .2s, border-color .2s;\n}\n.btn:active { transform: scale(.97); }\n.btn-pri { background: var(--coral); color: var(--noite); border: 1px solid var(--coral); }\n.btn-pri:hover { background: #ff7a69; }\n.btn-sec { border: 1px solid rgba(255, 255, 255, .3); }\n.btn-sec:hover { border-color: #fff; }\n.nota { margin: 16px 0 0; font-size: 14px; line-height: 1.5; color: rgba(255, 255, 255, .55); }\n.nota kbd, .nota code {\n  font-family: var(--mono); font-size: 12px; padding: 1px 5px; border-radius: 5px;\n  background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 255, 255, .12);\n}","baseHtml":"","criadoEm":1790619300000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* entrada do texto */\n.entra { opacity: 0; animation: entra .7s cubic-bezier(.2, .8, .2, 1) forwards; animation-delay: calc(var(--d) * 90ms + 150ms); }\n@keyframes entra { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }","descricao":"Ao abrir a página, a etiqueta, o título, o parágrafo e os botões sobem um depois do outro, com 90 ms entre cada um.","html":"<div class=\"texto\">\n        <p class=\"sobre entra\" style=\"--d:0\" data-texto=\"sobre\">Protótipo de animação</p>\n        <h1 class=\"entra\" style=\"--d:1\"><span class=\"h1-a\" data-texto=\"h1-branco\">Cada passo desenhado.</span><br><span class=\"h1-b\" data-texto=\"h1-coral\">Cada metro contado.</span></h1>\n        <p class=\"lead entra\" style=\"--d:2\" data-texto=\"lead\">Página de testes para movimento: relevo gerado por código, rota traçada em tempo real, contadores que acompanham o traçado e seções que aparecem ao rolar.</p>\n        <div class=\"acoes entra\" style=\"--d:3\">\n          <a class=\"btn btn-pri\" href=\"entrar.html\" data-texto=\"btn-1\">Começar</a>\n          <button class=\"btn btn-sec\" id=\"replay\" type=\"button\" data-texto=\"btn-2\">Rever animação</button>\n        </div>\n        <p class=\"nota entra\" style=\"--d:4\" data-texto=\"nota\">Atalhos: R reinicia · → próxima rota · ?speed=2 acelera.</p>\n      </div>\n</div>","js":"","noAr":true,"ordem":1,"pagina":"myrunning/index.html","secao":"Página inicial","secaoOrdem":1,"sistema":"myrunn.ing","tags":["texto","entrada"],"titulo":"Título e texto entrando em sequência"}$animasys$::jsonb)
