insert into public.animacoes (id, dados) values ('mr-fundo', $animasys${"atualizadoEm":1790619240000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #f4f3f0; }\nmain { min-height: 100vh; display: grid; place-items: center; }\n.cartao { display: grid; gap: 6px; padding: 28px 32px; background: #fff; border-radius: 14px; box-shadow: 0 10px 30px -18px rgba(0,0,0,.4); font: 16px \"Archivo\", system-ui; } .cartao b { font: 600 26px \"Outfit\", system-ui; }","baseHtml":"<main><div class=\"cartao\"><b>Entrar</b><span>O conteúdo fica limpo no centro.</span></div></main>","criadoEm":1790619240000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* ---------- fundo animado (fundo.js) ---------- */\n.fundo {\n  position: fixed; inset: 0; z-index: 0; pointer-events: none; overflow: hidden;\n  /* centro limpo onde fica o formulário; bordas com o relevo */\n  -webkit-mask-image: radial-gradient(ellipse 38% 58% at 50% 50%, transparent 30%, #000 88%);\n          mask-image: radial-gradient(ellipse 38% 58% at 50% 50%, transparent 30%, #000 88%);\n  opacity: 0; animation: fundo-in 1.6s ease-out .1s forwards;\n}\n@keyframes fundo-in { to { opacity: 1; } }\n.fundo svg { position: absolute; inset: -24px; width: calc(100% + 48px); height: calc(100% + 48px); }\n.fundo-relevo {\n  transform: translate(var(--px, 0px), var(--py, 0px));\n  transition: transform .2s linear;\n}\n.fundo-relevo { animation: fundo-deriva 38s ease-in-out infinite alternate; }\n@keyframes fundo-deriva {\n  from { translate: -10px 6px; scale: 1; }\n  to   { translate: 12px -8px; scale: 1.035; }\n}\n.fundo-curva { fill: none; stroke: var(--noite); stroke-opacity: .07; stroke-width: 1; stroke-linecap: round; }\n.fundo-curva.forte { stroke-opacity: .12; }\n.fundo-rota { fill: none; stroke: var(--coral); stroke-opacity: .55; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: opacity 1.4s ease; }\n.fundo-brilho { fill: none; stroke: var(--coral); stroke-opacity: .18; stroke-width: 10; stroke-linecap: round; filter: url(#fundo-suave); transition: opacity 1.4s ease; }\n.fundo-cabeca { fill: var(--coral); opacity: 0; }\nbody:has(.fundo) main, body:has(.fundo) footer { position: relative; z-index: 1; }\n@media (prefers-reduced-motion: reduce) {\n  .fundo { animation: none; opacity: 1; }\n  .fundo-relevo { animation: none; }\n}\n@media (max-width: 767px) {\n  .fundo { -webkit-mask-image: linear-gradient(to bottom, #000, transparent 22%, transparent 78%, #000);\n                   mask-image: linear-gradient(to bottom, #000, transparent 22%, transparent 78%, #000); }\n}","descricao":"Curvas de nível suaves que \"respiram\" nas bordas da tela e, de tempos em tempos, uma rota coral se desenha pela faixa de cima ou de baixo. O centro fica limpo para o conteúdo.","html":"","js":"/* trilha.lab — fundo animado da página Entrar:\n   curvas de nível que derivam devagar + uma rota coral que se desenha de tempos em tempos.\n   Fica atrás de tudo (pointer-events: none) e some perto do formulário (máscara no CSS). */\n(function () {\n  var NS = 'http://www.w3.org/2000/svg';\n  var REDUZIR = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var fundo = document.createElement('div');\n  fundo.className = 'fundo';\n  fundo.setAttribute('aria-hidden', 'true');\n  document.body.insertBefore(fundo, document.body.firstChild);\n\n  var svg, relevo, rota, brilho, cabeca, W, H, ciclo = 0;\n\n  // morros espalhados pela tela + ondulação suave\n  function campo(W, H) {\n    var morros = [[.12, .25, .16, 1], [.85, .2, .14, .8], [.9, .78, .18, .95], [.1, .82, .15, .7],\n                  [.5, .5, .2, -.5], [.32, .08, .1, .45], [.68, .95, .12, .5]];\n    var m = Math.max(W, H);\n    return function (x, y) {\n      var v = 0;\n      for (var i = 0; i < morros.length; i++) {\n        var k = morros[i], dx = x - k[0] * W, dy = y - k[1] * H, r = k[2] * m;\n        v += k[3] * Math.exp(-(dx * dx + dy * dy) / (2 * r * r));\n      }\n      return v + .1 * Math.sin(x * .006 + y * .004) + .06 * Math.sin(y * .009 - x * .005 + 1.3);\n    };\n  }\n\n  // marching squares → um <path> por nível\n  function desenhaRelevo() {\n    var altura = campo(W, H), PASSO = 9, M = 60;\n    var X0 = -M, Y0 = -M, cols = Math.ceil((W + 2 * M) / PASSO) + 1, rows = Math.ceil((H + 2 * M) / PASSO) + 1;\n    var g = [];\n    for (var j = 0; j < rows; j++) { g.push(new Float32Array(cols)); for (var i = 0; i < cols; i++) g[j][i] = altura(X0 + i * PASSO, Y0 + j * PASSO); }\n    relevo.innerHTML = '';\n    var n = 0;\n    for (var nivel = -.35; nivel <= 1.05; nivel += .1, n++) {\n      var d = [];\n      for (j = 0; j < rows - 1; j++) for (i = 0; i < cols - 1; i++) {\n        var a = g[j][i], b = g[j][i + 1], c = g[j + 1][i + 1], e = g[j + 1][i];\n        var caso = (a > nivel ? 8 : 0) | (b > nivel ? 4 : 0) | (c > nivel ? 2 : 0) | (e > nivel ? 1 : 0);\n        if (caso === 0 || caso === 15) continue;\n        var x = X0 + i * PASSO, y = Y0 + j * PASSO;\n        var T = [x + PASSO * (nivel - a) / (b - a), y], R = [x + PASSO, y + PASSO * (nivel - b) / (c - b)];\n        var B = [x + PASSO * (nivel - e) / (c - e), y + PASSO], L = [x, y + PASSO * (nivel - a) / (e - a)];\n        var segs = {1: [[L, B]], 2: [[B, R]], 3: [[L, R]], 4: [[T, R]], 5: [[T, R], [L, B]], 6: [[T, B]], 7: [[T, L]],\n                    8: [[T, L]], 9: [[T, B]], 10: [[T, L], [B, R]], 11: [[T, R]], 12: [[L, R]], 13: [[B, R]], 14: [[L, B]]}[caso];\n        for (var s = 0; s < segs.length; s++)\n          d.push('M' + segs[s][0][0].toFixed(1) + ' ' + segs[s][0][1].toFixed(1) + 'L' + segs[s][1][0].toFixed(1) + ' ' + segs[s][1][1].toFixed(1));\n      }\n      if (!d.length) continue;\n      var p = document.createElementNS(NS, 'path');\n      p.setAttribute('class', n % 4 === 1 ? 'fundo-curva forte' : 'fundo-curva');\n      p.setAttribute('d', d.join(''));\n      relevo.appendChild(p);\n    }\n  }\n\n  function suaviza(pts) {\n    var f = function (v) { return v.toFixed(1); };\n    var d = 'M' + f(pts[0][0]) + ' ' + f(pts[0][1]);\n    for (var i = 0; i < pts.length - 1; i++) {\n      var p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;\n      d += 'C' + f(p1[0] + (p2[0] - p0[0]) / 6) + ' ' + f(p1[1] + (p2[1] - p0[1]) / 6) + ' ' +\n                 f(p2[0] - (p3[0] - p1[0]) / 6) + ' ' + f(p2[1] - (p3[1] - p1[1]) / 6) + ' ' + f(p2[0]) + ' ' + f(p2[1]);\n    }\n    return d;\n  }\n\n  // rota nova a cada ciclo: entra por uma borda e sai pela outra, serpenteando\n  function novaRota() {\n    // alterna entre a faixa de cima e a de baixo, para nunca cruzar o formulário\n    var faixa = ciclo % 2 ? [.72, .9] : [.12, .28], lado = (ciclo >> 1) % 2, pts = [], N = 7;\n    ciclo++;\n    var sorteia = function () { return H * (faixa[0] + Math.random() * (faixa[1] - faixa[0])); };\n    var yIni = sorteia(), yFim = sorteia();\n    for (var i = 0; i < N; i++) {\n      var f = i / (N - 1);\n      var x = -40 + f * (W + 80);\n      var y = yIni + (yFim - yIni) * f + Math.sin(f * Math.PI * 2 + Math.random()) * H * .05;\n      pts.push([lado ? W - x : x, Math.max(H * faixa[0] - 20, Math.min(H * faixa[1] + 20, y))]);\n    }\n    return suaviza(pts);\n  }\n\n  function monta() {\n    W = innerWidth; H = innerHeight;\n    fundo.innerHTML = '';\n    svg = document.createElementNS(NS, 'svg');\n    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);\n    svg.setAttribute('preserveAspectRatio', 'xMidYMid slice');\n    svg.innerHTML =\n      '<defs><filter id=\"fundo-suave\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\"><feGaussianBlur stdDeviation=\"6\"/></filter></defs>' +\n      '<g class=\"fundo-relevo\"></g>' +\n      '<path class=\"fundo-brilho\"/><path class=\"fundo-rota\"/><circle class=\"fundo-cabeca\" r=\"4\"/>';\n    fundo.appendChild(svg);\n    relevo = svg.querySelector('.fundo-relevo');\n    brilho = svg.querySelector('.fundo-brilho');\n    rota = svg.querySelector('.fundo-rota');\n    cabeca = svg.querySelector('.fundo-cabeca');\n    desenhaRelevo();\n  }\n\n  var ficha = 0;\n  function espera(ms, f) { return new Promise(function (ok, nao) { setTimeout(function () { f === ficha ? ok() : nao(); }, ms); }); }\n  var vaivem = function (t) { return t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };\n\n  function tracaRota(f) {\n    var d = novaRota();\n    rota.setAttribute('d', d); brilho.setAttribute('d', d);\n    var len = rota.getTotalLength();\n    [rota, brilho].forEach(function (p) { p.style.strokeDasharray = len + ' ' + len; p.style.strokeDashoffset = len; p.style.opacity = ''; });\n    cabeca.style.opacity = 0;\n    if (REDUZIR) { rota.style.strokeDashoffset = brilho.style.strokeDashoffset = 0; return Promise.resolve(); }\n    var DUR = 5200 + len * 1.2;\n    return new Promise(function (ok, nao) {\n      var t0 = performance.now();\n      (function quadro(t) {\n        if (f !== ficha) return nao();\n        var p = Math.min(1, (t - t0) / DUR), e = vaivem(p), q = rota.getPointAtLength(len * e);\n        rota.style.strokeDashoffset = brilho.style.strokeDashoffset = len * (1 - e);\n        cabeca.setAttribute('cx', q.x); cabeca.setAttribute('cy', q.y);\n        cabeca.style.opacity = Math.min(1, p * 8, (1 - p) * 8);\n        p < 1 ? requestAnimationFrame(quadro) : ok();\n      })(t0);\n    });\n  }\n\n  async function laco(f) {\n    await espera(900, f);\n    for (;;) {\n      await tracaRota(f);\n      await espera(2200, f);\n      [rota, brilho].forEach(function (p) { p.style.opacity = 0; }); // some devagar (transição no CSS)\n      await espera(1600, f);\n    }\n  }\n\n  function inicia() { ficha++; monta(); if (!REDUZIR) laco(ficha).catch(function () {}); else tracaRota(ficha); }\n\n  var rt;\n  addEventListener('resize', function () {\n    if (Math.abs(innerWidth - W) < 40 && Math.abs(innerHeight - H) < 120) return; // ignora a barra do celular\n    clearTimeout(rt); rt = setTimeout(inicia, 250);\n  });\n\n  // leve paralaxe com o mouse (só em telas com ponteiro fino)\n  if (!REDUZIR && matchMedia('(pointer: fine)').matches) {\n    var alvo = [0, 0], atual = [0, 0], rodando = false;\n    addEventListener('pointermove', function (e) {\n      alvo = [(e.clientX / innerWidth - .5) * -14, (e.clientY / innerHeight - .5) * -10];\n      if (!rodando) { rodando = true; requestAnimationFrame(segue); }\n    });\n    function segue() {\n      atual[0] += (alvo[0] - atual[0]) * .06; atual[1] += (alvo[1] - atual[1]) * .06;\n      fundo.style.setProperty('--px', atual[0].toFixed(2) + 'px');\n      fundo.style.setProperty('--py', atual[1].toFixed(2) + 'px');\n      if (Math.abs(alvo[0] - atual[0]) + Math.abs(alvo[1] - atual[1]) > .05) requestAnimationFrame(segue); else rodando = false;\n    }\n  }\n\n  inicia();\n})();\n","noAr":true,"ordem":2,"pagina":"myrunning/entrar.html","secao":"Login","secaoOrdem":2,"sistema":"myrunn.ing","tags":["fundo","relevo"],"titulo":"Fundo com relevo e rotas"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
insert into public.animacoes (id, dados) values ('mr-mapa', $animasys${"atualizadoEm":1790618940000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #141416; }\nbody { display: grid; place-items: center; padding: 16px; }\n.palco { width: min(640px, 100%); }\n.rever { margin-top: 12px; font: 600 14px system-ui; padding: 8px 16px; border-radius: 10px; border: 1px solid rgba(255,255,255,.3); background: none; color: #fff; cursor: pointer; }\nbody { display: flex; flex-direction: column; align-items: center; justify-content: center; }","baseHtml":"","criadoEm":1790618940000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* ---------- palco / mapa ---------- */\n.palco {\n  position: relative; width: 100%; max-width: 640px; justify-self: center;\n  aspect-ratio: 600 / 520; overflow: hidden;\n  background: transparent;\n  font-family: var(--mono); color: #fff; user-select: none;\n  opacity: 0; transform: scale(.97);\n  animation: palco-in .9s cubic-bezier(.2, .8, .2, 1) .1s forwards;\n}\n@keyframes palco-in { to { opacity: 1; transform: none; } }\n.palco > svg#mapa { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n\n.camada { transition: transform 1.4s cubic-bezier(.2, .8, .2, 1); }\n.curva { fill: none; stroke: var(--lilas); stroke-opacity: .15; stroke-width: 1; stroke-linecap: round; }\n.curva.forte { stroke-opacity: .3; stroke-width: 1.2; }\n\n.fantasma { fill: none; stroke: #fff; stroke-opacity: 0; stroke-width: 1; stroke-dasharray: 2 7; stroke-linecap: round; transition: stroke-opacity .6s; }\n.fantasma.on { stroke-opacity: .16; }\n.brilho { fill: none; stroke: var(--coral); stroke-width: 12; stroke-linecap: round; stroke-linejoin: round; opacity: .28; filter: url(#suave); }\n.trilha { fill: none; stroke: var(--coral); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; transition: stroke .5s; }\n.trilha.flash { stroke: #fff; transition: none; }\n#rota { transition: opacity .6s; }\n#rota.sai { opacity: 0; }\n\n.cabeca { fill: #fff; }\n.cabeca-anel { fill: none; stroke: #fff; stroke-width: 1.2; opacity: .5; }\n\n[data-wp] {\n  fill: var(--noite); stroke: #fff; stroke-width: 1.8; opacity: 0;\n  transform-box: fill-box; transform-origin: center; transform: scale(.5);\n  transition: opacity .25s, transform .45s cubic-bezier(.2, 1.5, .4, 1);\n}\n[data-wp].on { opacity: 1; transform: scale(1); }\n[data-anel] { fill: none; stroke: var(--coral); stroke-width: 1.5; opacity: 0; transform-box: fill-box; transform-origin: center; }\n[data-anel].on { animation: anel 1s cubic-bezier(.1, .7, .3, 1) 1; }\n@keyframes anel { 0% { opacity: .9; transform: scale(.4); } 100% { opacity: 0; transform: scale(3.2); } }\n\n.sonar { fill: none; stroke: #fff; stroke-width: 1; opacity: 0; transform-box: fill-box; transform-origin: center; }\n.sonar.on { animation: sonar 1.6s ease-out infinite; }\n.sonar.s2.on { animation-delay: .5s; }\n.sonar.s3.on { animation-delay: 1s; }\n@keyframes sonar { 0% { opacity: .7; transform: scale(.2); } 100% { opacity: 0; transform: scale(4); } }\n\n.perfil-base { stroke: #fff; stroke-opacity: .14; }\n.perfil-linha { fill: none; stroke: var(--coral); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }\n.perfil-area { fill: url(#perfil-grad); }\n.perfil-cursor { fill: #fff; }\n\n/* HUD */\n.hud { position: absolute; left: 22px; top: 20px; display: flex; gap: 22px; }\n.hud .m { display: flex; flex-direction: column; gap: 3px; }\n.hud small { font: 700 9px var(--sans); letter-spacing: .16em; text-transform: uppercase; color: rgba(255, 255, 255, .45); }\n.hud b { font-size: 17px; font-weight: 500; font-variant-numeric: tabular-nums; letter-spacing: -.01em; line-height: 1; }\n.hud b i { font-style: normal; font-size: 10px; color: rgba(255, 255, 255, .45); margin-left: 3px; font-weight: 400; }\n@media (max-width: 420px) { .hud { gap: 14px; left: 16px; } .hud b { font-size: 14px; } }\n\n.selo { position: absolute; right: 22px; top: 20px; width: 26px; height: 26px; color: #fff; opacity: .55; transition: opacity .4s; }\n.selo.some { opacity: 0; }\n\n.pronto {\n  position: absolute; right: 22px; top: 20px;\n  display: flex; align-items: center; gap: 8px;\n  padding: 7px 11px 7px 9px; border-radius: 999px;\n  background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 255, 255, .12);\n  backdrop-filter: blur(6px);\n  font: 600 11.5px var(--sans); color: #fff;\n  opacity: 0; transform: translateY(-6px);\n  transition: opacity .45s, transform .45s cubic-bezier(.2, .8, .2, 1);\n}\n.pronto.on { opacity: 1; transform: none; }\n.pronto svg { width: 14px; height: 14px; }\n\n.escala { position: absolute; right: 22px; bottom: 58px; display: flex; align-items: center; gap: 6px; font-size: 9px; letter-spacing: .1em; color: rgba(255, 255, 255, .4); }\n.escala i { display: block; width: 40px; height: 1px; background: rgba(255, 255, 255, .35); position: relative; }\n.escala i::before, .escala i::after { content: \"\"; position: absolute; top: -2px; width: 1px; height: 5px; background: rgba(255, 255, 255, .35); }\n.escala i::after { right: 0; }\n\n.status {\n  position: absolute; left: 22px; bottom: 20px;\n  display: flex; align-items: center; gap: 8px;\n  font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: rgba(255, 255, 255, .6);\n}\n.status i { width: 6px; height: 6px; border-radius: 50%; background: var(--coral); box-shadow: 0 0 0 0 rgba(255, 99, 79, .6); animation: pulso 1.6s infinite; }\n.status i.ok { background: var(--verde); animation: none; box-shadow: none; }\n@keyframes pulso { 100% { box-shadow: 0 0 0 8px rgba(255, 99, 79, 0); } }\n\n.nome-rota { position: absolute; right: 22px; bottom: 20px; text-align: right; font-family: var(--sans); }\n.nome-rota b { display: block; font-size: 13px; font-weight: 600; letter-spacing: -.01em; }\n.nome-rota span { font-size: 11px; color: rgba(255, 255, 255, .5); }\n.nome-rota b, .nome-rota span { transition: opacity .4s; }\n.nome-rota.troca b, .nome-rota.troca span { opacity: 0; }","descricao":"Curvas de nível geradas por código, a rota se desenha com brilho, os pontos de passagem pulsam, distância/tempo/ritmo/FC sobem junto e o selo \"Rota pronta\" entra no fim. Troca de rota sozinha.","html":"<div class=\"palco\" id=\"palco\">\n        <svg id=\"mapa\" viewBox=\"0 0 600 520\" aria-hidden=\"true\">\n          <defs>\n            <filter id=\"suave\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feGaussianBlur stdDeviation=\"5\"/></filter>\n            <radialGradient id=\"vinheta\" cx=\"50%\" cy=\"45%\" r=\"70%\">\n              <stop offset=\"55%\" stop-color=\"#141416\" stop-opacity=\"0\"/>\n              <stop offset=\"100%\" stop-color=\"#141416\" stop-opacity=\".85\"/>\n            </radialGradient>\n            <linearGradient id=\"perfil-grad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n              <stop offset=\"0\" stop-color=\"#ff634f\" stop-opacity=\".35\"/>\n              <stop offset=\"1\" stop-color=\"#ff634f\" stop-opacity=\"0\"/>\n            </linearGradient>\n            <pattern id=\"pontos\" width=\"14\" height=\"14\" patternUnits=\"userSpaceOnUse\"><circle cx=\"1\" cy=\"1\" r=\".7\" fill=\"#fff\" fill-opacity=\".05\"/></pattern>\n            <radialGradient id=\"fade-g\" cx=\"50%\" cy=\"48%\" r=\"58%\">\n              <stop offset=\"60%\" stop-color=\"#fff\"/>\n              <stop offset=\"100%\" stop-color=\"#000\"/>\n            </radialGradient>\n            <mask id=\"fade\"><rect width=\"600\" height=\"520\" fill=\"url(#fade-g)\"/></mask>\n            <clipPath id=\"perfil-clip\"><rect id=\"perfil-rev\" x=\"0\" y=\"0\" width=\"0\" height=\"520\"/></clipPath>\n          </defs>\n          <g mask=\"url(#fade)\"><g id=\"relevo\" class=\"camada\"></g></g>\n          <g id=\"rota\">\n            <path id=\"fantasma\" class=\"fantasma\"/>\n            <path id=\"brilho\" class=\"brilho\"/>\n            <path id=\"trilha\" class=\"trilha\"/>\n            <g id=\"pontos-rota\"></g>\n            <circle class=\"sonar\" r=\"6\"/><circle class=\"sonar s2\" r=\"6\"/><circle class=\"sonar s3\" r=\"6\"/>\n            <circle id=\"cabeca-anel\" class=\"cabeca-anel\" r=\"9\"/>\n            <circle id=\"cabeca\" class=\"cabeca\" r=\"4.5\"/>\n          </g>\n          <g id=\"perfil\">\n            <line class=\"perfil-base\" x1=\"22\" x2=\"578\" y1=\"452\" y2=\"452\"/>\n            <g clip-path=\"url(#perfil-clip)\">\n              <path id=\"perfil-area\" class=\"perfil-area\"/>\n              <path id=\"perfil-linha\" class=\"perfil-linha\"/>\n            </g>\n            <circle id=\"perfil-cursor\" class=\"perfil-cursor\" r=\"2.6\"/>\n          </g>\n        </svg>\n\n        <div class=\"hud\">\n          <div class=\"m\"><small>Distância</small><b id=\"h-dist\">0,00<i>km</i></b></div>\n          <div class=\"m\"><small>Tempo</small><b id=\"h-tempo\">0:00:00</b></div>\n          <div class=\"m\"><small>Ritmo</small><b id=\"h-ritmo\">0:00<i>/km</i></b></div>\n          <div class=\"m\"><small>FC</small><b id=\"h-fc\">0<i>bpm</i></b></div>\n        </div>\n        <svg class=\"selo\" id=\"selo\" viewBox=\"0 0 32 32\" aria-hidden=\"true\"><circle cx=\"16\" cy=\"16\" r=\"15\" fill=\"currentColor\"/><path d=\"M8 21c3-1 3-7 7-8s4 5 9 2\" fill=\"none\" stroke=\"#141416\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg>\n        <div class=\"pronto\" id=\"pronto\">\n          <svg viewBox=\"0 0 16 16\"><circle cx=\"8\" cy=\"8\" r=\"7.5\" fill=\"#8fe3b0\"/><path d=\"M4.6 8.3l2.2 2.2 4.6-4.9\" fill=\"none\" stroke=\"#141416\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n          <span id=\"pronto-txt\">Rota pronta</span>\n        </div>\n        <div class=\"escala\"><i></i><span>1 KM</span></div>\n        <div class=\"status\"><i id=\"status-dot\"></i><span id=\"status-txt\">Traçando rota</span></div>\n        <div class=\"nome-rota\"><b id=\"rota-nome\">—</b><span id=\"rota-sub\">—</span></div>\n      </div>\n<button id=\"replay\" type=\"button\" class=\"rever\">Rever animação</button>","js":"/* trilha.lab — mapa topográfico + rota animada (código próprio, só para testes). */\n(function () {\n  var W = 600, H = 520;\n  var NS = 'http://www.w3.org/2000/svg';\n  var params = new URLSearchParams(location.search);\n  var SPEED = parseFloat(params.get('speed')) || 1;\n  var REDUZIR = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* ---------- relevo: soma de morros gaussianos + ondulação ---------- */\n  var MORROS = [[170, 170, 95, 1], [440, 320, 120, .95], [310, 430, 80, -.55],\n                [490, 110, 70, .55], [110, 420, 90, .45], [300, 260, 60, -.35]];\n  function altura(x, y) {\n    var v = 0;\n    for (var i = 0; i < MORROS.length; i++) {\n      var m = MORROS[i], dx = x - m[0], dy = y - m[1];\n      v += m[3] * Math.exp(-(dx * dx + dy * dy) / (2 * m[2] * m[2]));\n    }\n    return v + .1 * Math.sin(x * .014 + y * .009) + .06 * Math.sin(y * .022 - x * .011 + 1.3);\n  }\n\n  /* marching squares → um <path> por nível */\n  function desenhaRelevo(g) {\n    var PASSO = 5, X0 = -80, Y0 = -80, X1 = W + 80, Y1 = H + 80;\n    var cols = Math.ceil((X1 - X0) / PASSO) + 1, rows = Math.ceil((Y1 - Y0) / PASSO) + 1;\n    var grade = [];\n    for (var j = 0; j < rows; j++) {\n      grade.push(new Float32Array(cols));\n      for (var i = 0; i < cols; i++) grade[j][i] = altura(X0 + i * PASSO, Y0 + j * PASSO);\n    }\n    var n = 0;\n    for (var nivel = -.45; nivel <= 1.1; nivel += .17, n++) {\n      var d = [];\n      for (j = 0; j < rows - 1; j++) for (i = 0; i < cols - 1; i++) {\n        var a = grade[j][i], b = grade[j][i + 1], c = grade[j + 1][i + 1], e = grade[j + 1][i];\n        var caso = (a > nivel ? 8 : 0) | (b > nivel ? 4 : 0) | (c > nivel ? 2 : 0) | (e > nivel ? 1 : 0);\n        if (caso === 0 || caso === 15) continue;\n        var x = X0 + i * PASSO, y = Y0 + j * PASSO;\n        var T = [x + PASSO * (nivel - a) / (b - a), y];\n        var R = [x + PASSO, y + PASSO * (nivel - b) / (c - b)];\n        var B = [x + PASSO * (nivel - e) / (c - e), y + PASSO];\n        var L = [x, y + PASSO * (nivel - a) / (e - a)];\n        var segs = {1: [[L, B]], 2: [[B, R]], 3: [[L, R]], 4: [[T, R]], 5: [[T, R], [L, B]], 6: [[T, B]], 7: [[T, L]],\n                    8: [[T, L]], 9: [[T, B]], 10: [[T, L], [B, R]], 11: [[T, R]], 12: [[L, R]], 13: [[B, R]], 14: [[L, B]]}[caso];\n        for (var s = 0; s < segs.length; s++)\n          d.push('M' + segs[s][0][0].toFixed(1) + ' ' + segs[s][0][1].toFixed(1) + 'L' + segs[s][1][0].toFixed(1) + ' ' + segs[s][1][1].toFixed(1));\n      }\n      if (!d.length) continue;\n      var p = document.createElementNS(NS, 'path');\n      p.setAttribute('class', n % 3 === 2 ? 'curva forte' : 'curva');\n      p.setAttribute('d', d.join(''));\n      g.appendChild(p);\n    }\n  }\n\n  /* Catmull-Rom → Bézier */\n  function suaviza(pts) {\n    var f = function (v) { return v.toFixed(1); };\n    var d = 'M' + f(pts[0][0]) + ' ' + f(pts[0][1]);\n    for (var i = 0; i < pts.length - 1; i++) {\n      var p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;\n      d += 'C' + f(p1[0] + (p2[0] - p0[0]) / 6) + ' ' + f(p1[1] + (p2[1] - p0[1]) / 6) + ' ' +\n                 f(p2[0] - (p3[0] - p1[0]) / 6) + ' ' + f(p2[1] - (p3[1] - p1[1]) / 6) + ' ' + f(p2[0]) + ' ' + f(p2[1]);\n    }\n    return d;\n  }\n\n  /* ---------- rotas de exemplo ---------- */\n  var ROTAS = [\n    { nome: 'Trilha do Açude', sub: 'Corrida · manhã', km: 8.1, ritmo: 372, fc: 142, camera: [0, 0, 1],\n      pts: [[70, 380], [120, 350], [150, 300], [140, 240], [190, 200], [260, 190], [300, 150], [290, 110], [350, 95], [420, 115], [470, 165], [500, 235], [470, 300], [420, 330]],\n      wps: [3, 7, 11] },\n    { nome: 'Volta da Represa', sub: 'Caminhada · tarde', km: 5.4, ritmo: 648, fc: 104, camera: [-40, 25, 1.06],\n      pts: [[300, 370], [240, 350], [190, 310], [175, 250], [205, 190], [270, 155], [345, 150], [410, 180], [440, 240], [420, 305], [365, 345], [310, 372]],\n      wps: [2, 5, 8] },\n    { nome: 'Serra Baixa', sub: 'Trail · 21 km', km: 21.3, ritmo: 455, fc: 156, camera: [30, -20, 1.1],\n      pts: [[540, 380], [490, 350], [470, 290], [420, 260], [360, 280], [300, 240], [250, 260], [190, 230], [150, 170], [100, 140], [60, 100]],\n      wps: [2, 5, 8] }\n  ];\n\n  /* ---------- elementos ---------- */\n  var $ = function (id) { return document.getElementById(id); };\n  var relevo = $('relevo'), rota = $('rota'), fantasma = $('fantasma'), brilho = $('brilho'), trilha = $('trilha');\n  var cabeca = $('cabeca'), anel = $('cabeca-anel'), pontosRota = $('pontos-rota');\n  var sonares = rota.querySelectorAll('.sonar');\n  var perfilLinha = $('perfil-linha'), perfilArea = $('perfil-area'), perfilRev = $('perfil-rev'), perfilCursor = $('perfil-cursor');\n  var hDist = $('h-dist'), hTempo = $('h-tempo'), hRitmo = $('h-ritmo'), hFc = $('h-fc');\n  var selo = $('selo'), pronto = $('pronto'), prontoTxt = $('pronto-txt');\n  var statusDot = $('status-dot'), statusTxt = $('status-txt'), rotaNome = $('rota-nome'), rotaSub = $('rota-sub');\n  var nomeBox = rotaNome.parentNode;\n\n  desenhaRelevo(relevo);\n\n  /* ---------- formatação ---------- */\n  var virgula = function (v, c) { return v.toFixed(c).replace('.', ','); };\n  function hms(s) { s = Math.round(s); var h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60; return h + ':' + (m < 10 ? '0' : '') + m + ':' + (x < 10 ? '0' : '') + x; }\n  function ms(s) { s = Math.round(s); var m = Math.floor(s / 60), x = s % 60; return m + ':' + (x < 10 ? '0' : '') + x; }\n\n  /* ---------- controle de execução ---------- */\n  var ficha = 0, atual = 0;\n  function espera(ms, f) { return new Promise(function (ok, nao) { setTimeout(function () { f === ficha ? ok() : nao('cancelado'); }, ms / SPEED); }); }\n  function anima(dur, f, cada) {\n    return new Promise(function (ok, nao) {\n      var t0 = performance.now();\n      (function passo(t) {\n        if (f !== ficha) return nao('cancelado');\n        var p = Math.min(1, (t - t0) * SPEED / dur);\n        cada(p);\n        p < 1 ? requestAnimationFrame(passo) : ok();\n      })(t0);\n    });\n  }\n  var suave = function (t) { return t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };\n\n  /* ---------- montar uma rota ---------- */\n  function monta(r) {\n    var d = suaviza(r.pts);\n    [fantasma, brilho, trilha].forEach(function (p) { p.setAttribute('d', d); });\n    var len = trilha.getTotalLength();\n    [brilho, trilha].forEach(function (p) { p.style.strokeDasharray = len; p.style.strokeDashoffset = len; });\n\n    // pontos de passagem na posição (fração do comprimento) mais próxima de cada ponto\n    pontosRota.innerHTML = '';\n    var amostras = [], N = 160;\n    for (var i = 0; i <= N; i++) { var q = trilha.getPointAtLength(len * i / N); amostras.push([q.x, q.y, altura(q.x, q.y)]); }\n    var wps = r.wps.map(function (k) {\n      var alvo = r.pts[k], melhor = 0, dm = 1e9;\n      amostras.forEach(function (a, i) { var dd = (a[0] - alvo[0]) * (a[0] - alvo[0]) + (a[1] - alvo[1]) * (a[1] - alvo[1]); if (dd < dm) { dm = dd; melhor = i; } });\n      var a = amostras[melhor];\n      var anelEl = document.createElementNS(NS, 'circle'); anelEl.setAttribute('r', 5); anelEl.setAttribute('cx', a[0]); anelEl.setAttribute('cy', a[1]); anelEl.setAttribute('data-anel', '');\n      var wp = document.createElementNS(NS, 'circle'); wp.setAttribute('r', 4.5); wp.setAttribute('cx', a[0]); wp.setAttribute('cy', a[1]); wp.setAttribute('data-wp', '');\n      pontosRota.appendChild(anelEl); pontosRota.appendChild(wp);\n      return { p: melhor / N, wp: wp, anel: anelEl };\n    });\n    // início e fim\n    [0, N].forEach(function (i) {\n      var c = document.createElementNS(NS, 'circle'); c.setAttribute('r', i ? 5.5 : 3.5); c.setAttribute('cx', amostras[i][0]); c.setAttribute('cy', amostras[i][1]);\n      c.setAttribute('data-wp', ''); if (!i) c.classList.add('on'); pontosRota.appendChild(c);\n      if (i) wps.push({ p: 1, wp: c, anel: null });\n    });\n\n    // perfil de elevação\n    var mn = Math.min.apply(null, amostras.map(function (a) { return a[2]; }));\n    var mx = Math.max.apply(null, amostras.map(function (a) { return a[2]; }));\n    var px = function (i) { return 22 + 556 * i / N; };\n    var py = function (h) { return 450 - 34 * (h - mn) / (mx - mn || 1); };\n    var linha = amostras.map(function (a, i) { return (i ? 'L' : 'M') + px(i).toFixed(1) + ' ' + py(a[2]).toFixed(1); }).join('');\n    perfilLinha.setAttribute('d', linha);\n    perfilArea.setAttribute('d', linha + 'L578 452L22 452Z');\n    var ganho = 0; for (i = 1; i <= N; i++) ganho += Math.max(0, amostras[i][2] - amostras[i - 1][2]);\n\n    return { len: len, amostras: amostras, wps: wps, px: px, py: py, N: N, ganho: Math.round(ganho * 180) };\n  }\n\n  function hud(r, m, p) {\n    var i = Math.min(m.N, Math.round(p * m.N)), a = m.amostras[i], b = m.amostras[Math.max(0, i - 4)];\n    var incl = Math.max(-1, Math.min(1, (a[2] - b[2]) * 8)); // -1 descendo … 1 subindo\n    var dist = r.km * p;\n    hDist.innerHTML = virgula(dist, 2) + '<i>km</i>';\n    hTempo.textContent = hms(dist * r.ritmo);\n    hRitmo.innerHTML = (p ? ms(r.ritmo * (1 + incl * .18)) : '0:00') + '<i>/km</i>';\n    hFc.innerHTML = (p ? Math.round(r.fc - 18 + 18 * Math.min(1, p * 4) + incl * 8) : 0) + '<i>bpm</i>';\n  }\n\n  function posiciona(m, p) {\n    var q = trilha.getPointAtLength(m.len * p);\n    cabeca.setAttribute('cx', q.x); cabeca.setAttribute('cy', q.y);\n    anel.setAttribute('cx', q.x); anel.setAttribute('cy', q.y);\n    sonares.forEach(function (s) { s.setAttribute('cx', q.x); s.setAttribute('cy', q.y); });\n    var off = m.len * (1 - p);\n    trilha.style.strokeDashoffset = off; brilho.style.strokeDashoffset = off;\n    perfilRev.setAttribute('width', m.px(p * m.N));\n    var i = Math.round(p * m.N);\n    perfilCursor.setAttribute('cx', m.px(i)); perfilCursor.setAttribute('cy', m.py(m.amostras[i][2]));\n  }\n\n  async function toca(idx, f) {\n    var r = ROTAS[idx];\n    // saída da rota anterior\n    rota.classList.add('sai'); nomeBox.classList.add('troca'); pronto.classList.remove('on');\n    sonares.forEach(function (s) { s.classList.remove('on'); });\n    var c = r.camera; relevo.style.transform = 'translate(' + c[0] + 'px,' + c[1] + 'px) scale(' + c[2] + ')';\n    await espera(600, f);\n\n    var m = monta(r);\n    fantasma.classList.remove('on'); posiciona(m, 0); hud(r, m, 0);\n    rotaNome.textContent = r.nome; rotaSub.textContent = r.sub;\n    statusDot.classList.remove('ok'); statusTxt.textContent = 'Traçando rota'; selo.classList.remove('some');\n    rota.classList.remove('sai'); nomeBox.classList.remove('troca');\n    await espera(350, f);\n    fantasma.classList.add('on');\n    await espera(700, f);\n\n    var duracao = 4200 + r.km * 120;\n    await anima(duracao, f, function (t) {\n      var p = suave(t);\n      posiciona(m, p); hud(r, m, p);\n      m.wps.forEach(function (w) {\n        if (p >= w.p && !w.wp.classList.contains('on')) { w.wp.classList.add('on'); if (w.anel) w.anel.classList.add('on'); }\n      });\n    });\n\n    // conclusão\n    trilha.classList.add('flash');\n    await espera(90, f);\n    trilha.classList.remove('flash');\n    sonares.forEach(function (s) { s.classList.add('on'); });\n    statusDot.classList.add('ok'); statusTxt.textContent = 'Rota concluída';\n    prontoTxt.textContent = 'Rota pronta · ' + virgula(r.km, 1) + ' km · +' + m.ganho + ' m';\n    selo.classList.add('some'); pronto.classList.add('on');\n    await espera(4200, f);\n    atual = (idx + 1) % ROTAS.length;\n    toca(atual, f).catch(function () {});\n  }\n\n  function estatico(idx) {\n    var r = ROTAS[idx], m = monta(r);\n    fantasma.classList.add('on'); posiciona(m, 1); hud(r, m, 1);\n    m.wps.forEach(function (w) { w.wp.classList.add('on'); });\n    rotaNome.textContent = r.nome; rotaSub.textContent = r.sub;\n    statusDot.classList.add('ok'); statusTxt.textContent = 'Rota concluída';\n    prontoTxt.textContent = 'Rota pronta · ' + virgula(r.km, 1) + ' km · +' + m.ganho + ' m';\n    selo.classList.add('some'); pronto.classList.add('on');\n  }\n\n  function inicia(idx) {\n    ficha++;\n    atual = idx;\n    if (REDUZIR) return estatico(idx);\n    toca(idx, ficha).catch(function () {});\n  }\n\n  $('replay').addEventListener('click', function () { inicia(atual); });\n  document.addEventListener('keydown', function (e) {\n    if (e.target.closest('input, textarea')) return;\n    if (e.key === 'r' || e.key === 'R') inicia(atual);\n    if (e.key === 'ArrowRight') inicia((atual + 1) % ROTAS.length);\n    if (e.key === 'ArrowLeft') inicia((atual + ROTAS.length - 1) % ROTAS.length);\n  });\n\n  inicia(+params.get('rota') || 0);\n})();","noAr":true,"ordem":2,"pagina":"myrunning/index.html","secao":"Página inicial","secaoOrdem":1,"sistema":"myrunn.ing","tags":["mapa","rota"],"titulo":"Mapa com rota traçada e contadores"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
insert into public.animacoes (id, dados) values ('mr-olho', $animasys${"atualizadoEm":1790619180000,"baseCss":"* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; font-family: \"Archivo\", system-ui, sans-serif; background: #f4f3f0; }\nbody { display: grid; place-items: center; }\n.caixa { width: min(352px, 90vw); }","baseHtml":"<div class=\"caixa\"><!--ANIMACAO--></div>","criadoEm":1790619180000,"css":"/* fontes usadas: Archivo, Outfit e JetBrains Mono (Google Fonts) */\n@import url(\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Outfit:wght@500;600&display=swap\");\n:root {\n  --noite: #141416;\n  --noite-medio: #3b3b42;\n  --noite-claro: #66666e;\n  --papel: #f4f3f0;\n  --coral: #ff634f;\n  --coral-escuro: #d9432f;\n  --lilas: #d6b8f7;\n  --verde: #8fe3b0;\n  --sans: \"Archivo\", system-ui, sans-serif;\n  --marca: \"Outfit\", \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n.rotulo { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; color: var(--noite-medio); }\n.campo {\n  display: block; width: 100%; height: 40px; padding: 0 12px;\n  font: 400 16px var(--sans); color: var(--noite);\n  background: #fff; border: 1px solid rgba(20, 20, 22, .5); border-radius: 12px;\n  outline: 1.6px solid transparent; outline-offset: 1.6px;\n  transition: border-color .15s, outline-color .15s;\n}\n.campo:focus { border-color: var(--noite); outline-color: rgba(20, 20, 22, .25); }\n.campo-senha { position: relative; }\n.campo-senha .campo { padding-right: 48px; }\n.mostrar {\n  position: absolute; right: 4px; top: 50%; transform: translateY(-50%);\n  width: 36px; height: 36px; padding: 0; border: 0; border-radius: 8px; background: none; cursor: pointer;\n  display: grid; place-items: center;\n  color: var(--noite-medio); transition: background .15s, color .15s;\n}\n.mostrar:hover { background: rgba(20, 20, 22, .05); color: var(--noite); }\n.mostrar:focus-visible { outline: 2px solid var(--noite); outline-offset: 1px; }\n\n/* olho: fechado = senha escondida; aberto = senha visível (desenhado em entrar.html) */\n.olho { width: 22px; height: 22px; overflow: visible; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.olho-pupila { fill: currentColor; stroke: none; }\n.olho-brilho { fill: #fff; stroke: none; opacity: 0; }\n.mostrar[aria-pressed=\"true\"] { color: var(--noite); }\n.mostrar:hover .olho { transform: scale(1.06); }\n.olho { transition: transform .2s cubic-bezier(.2, .8, .2, 1); }\n\n/* senha aparece suavemente ao trocar de estado */\n.campo.revela { animation: revela-senha .3s ease-out; }\n@keyframes revela-senha { from { color: rgba(20, 20, 22, 0); } to { color: var(--noite); } }\n\n/* olho: fechado = senha escondida; aberto = senha visível (desenhado em entrar.html) */\n.olho { width: 22px; height: 22px; overflow: visible; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.olho-pupila { fill: currentColor; stroke: none; }\n.olho-brilho { fill: #fff; stroke: none; opacity: 0; }\n.mostrar[aria-pressed=\"true\"] { color: var(--noite); }\n.mostrar:hover .olho { transform: scale(1.06); }\n.olho { transition: transform .2s cubic-bezier(.2, .8, .2, 1); }\n\n/* senha aparece suavemente ao trocar de estado */\n.campo.revela { animation: revela-senha .3s ease-out; }\n@keyframes revela-senha { from { color: rgba(20, 20, 22, 0); } to { color: var(--noite); } }\n.lembrar { display: flex; align-items: center; gap: 12px; min-height: 44px; cursor: pointer; font-size: 14px; line-height: 20px; color: var(--noite-medio); }\n.lembrar input { width: 20px; height: 20px; margin: 0; flex-shrink: 0; accent-color: var(--noite); }\n.btn-entrar {\n  width: 100%; height: 40px; padding: 0 16px; border: 0; border-radius: 12px; cursor: pointer;\n  background: var(--coral); color: var(--noite);\n  font: 700 14px/20px var(--sans); letter-spacing: -.025em;\n  transition: background .2s, transform .15s;\n}\n.btn-entrar:hover { background: #ff7a69; }\n.btn-entrar:active { transform: scale(.98); }\n.entrar-rodape {\n  margin: 0; padding-top: 16px; font-size: 14px; line-height: 1.625; color: var(--noite-claro);\n  /* linha divisória como fundo (dá para \"traçar\" na animação de entrada) */\n  background: linear-gradient(rgba(20, 20, 22, .1), rgba(20, 20, 22, .1)) no-repeat left top / 100% 1px;\n}\n\n/* animação de entrada (entrada.js) */\n.entrada-js .entrar > *, .entrada-js .entrar-form > *, .entrada-js .fundo { opacity: 0; }\n.contorno { position: absolute; pointer-events: none; overflow: visible; }\n.contorno path { fill: none; stroke: rgba(20, 20, 22, .5); stroke-width: 1; stroke-linecap: round; stroke-dasharray: 1 1; }\n.entrar-rodape span:first-child { font-weight: 600; color: var(--noite-medio); }","descricao":"Botão de mostrar senha: fechado com cílios quando a senha está escondida; ao clicar, a pálpebra sobe com um quique, a pupila surge, dá uma olhadinha para a senha e depois pisca de vez em quando.","html":"<label class=\"rotulo\" for=\"senha\">Senha</label>\n<div class=\"campo-senha\">\n          <input class=\"campo\" id=\"senha\" type=\"password\" autocomplete=\"off\">\n          <button type=\"button\" class=\"mostrar\" id=\"mostrar\" aria-pressed=\"false\" aria-label=\"Mostrar senha\" title=\"Mostrar senha\">\n            <svg class=\"olho\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n              <defs><clipPath id=\"olho-abertura\"><path id=\"olho-clip\"/></clipPath></defs>\n              <g clip-path=\"url(#olho-abertura)\">\n                <g id=\"olho-iris\">\n                  <circle class=\"olho-pupila\" id=\"olho-pupila\" cx=\"12\" cy=\"12\" r=\"3.4\"/>\n                  <circle class=\"olho-brilho\" id=\"olho-brilho\" cx=\"13.3\" cy=\"10.7\" r=\"1\"/>\n                </g>\n              </g>\n              <path class=\"olho-palpebra\" id=\"olho-baixo\"/>\n              <path class=\"olho-palpebra\" id=\"olho-cima\"/>\n              <g id=\"olho-cilios\">\n                <path d=\"M7.2 14.4l-1.3 2.3\"/><path d=\"M12 15.3v2.6\"/><path d=\"M16.8 14.4l1.3 2.3\"/>\n              </g>\n            </svg>\n          </button>\n        </div>","js":"/* olho: fechado = senha escondida; abre ao mostrar a senha */\n(function () {\n  var senha = document.getElementById('senha'), mostrar = document.getElementById('mostrar');\n  var $ = function (id) { return document.getElementById(id); };\n  var cima = $('olho-cima'), baixo = $('olho-baixo'), clip = $('olho-clip'), iris = $('olho-iris'),\n      pupila = $('olho-pupila'), brilho = $('olho-brilho'), cilios = $('olho-cilios');\n  var REDUZIR = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var estado = 0, anim = null, piscaTimer = null;\n\n  var lerp = function (a, b, t) { return a + (b - a) * t; };\n  var sai = function (t) { return 1 - Math.pow(1 - t, 3); };\n  var mola = function (t) { var s = 1.6; t -= 1; return t * t * ((s + 1) * t + s) + 1; }; // leve passada do ponto\n\n  // t = 0 fechado … 1 aberto. Pálpebras são curvas cúbicas entre os cantos (2.5,12) e (21.5,12).\n  function desenha(t) {\n    var tc = Math.max(0, t);\n    var cyCima = lerp(15.3, 2.7, t);                // ápice: 14.5 fechado → 5 aberto\n    var cyBaixo = lerp(15.3, 21.3, Math.min(1, tc)); // ápice: 14.5 → 19\n    var c = function (cy) { return 'C6 ' + cy.toFixed(2) + ' 18 ' + cy.toFixed(2) + ' 21.5 12'; };\n    cima.setAttribute('d', 'M2.5 12' + c(cyCima));\n    baixo.setAttribute('d', 'M2.5 12' + c(cyBaixo));\n    baixo.style.opacity = Math.min(1, tc * 2.5);\n    clip.setAttribute('d', 'M2.5 12' + c(cyCima) + 'C18 ' + cyBaixo.toFixed(2) + ' 6 ' + cyBaixo.toFixed(2) + ' 2.5 12Z');\n    var r = Math.max(0, lerp(1.2, 3.4, mola(Math.min(1, tc))));\n    pupila.setAttribute('r', r.toFixed(2));\n    brilho.style.opacity = Math.max(0, (tc - .55) / .45);\n    // cílios acompanham a pálpebra e somem conforme ela sobe\n    var q = Math.min(1, tc * 2.2);\n    cilios.style.opacity = 1 - q;\n    cilios.setAttribute('transform', 'translate(0 ' + (-q * 3).toFixed(2) + ')');\n  }\n\n  function vai(para, dur, curva) {\n    if (anim) cancelAnimationFrame(anim);\n    var de = estado, t0 = performance.now();\n    if (REDUZIR) { estado = para; desenha(para); return Promise.resolve(); }\n    return new Promise(function (ok) {\n      (function quadro(t) {\n        var p = Math.min(1, (t - t0) / dur);\n        estado = lerp(de, para, curva(p));\n        desenha(estado);\n        if (p < 1) anim = requestAnimationFrame(quadro); else { anim = null; ok(); }\n      })(t0);\n    });\n  }\n\n  // depois de abrir, a pupila dá uma olhadinha para a senha e volta\n  function olhadinha() {\n    if (REDUZIR) return;\n    iris.animate([\n      { transform: 'translate(0,0)' },\n      { transform: 'translate(-2.3px,.4px)', offset: .3 },\n      { transform: 'translate(-2.3px,.4px)', offset: .65 },\n      { transform: 'translate(0,0)' }\n    ], { duration: 1100, easing: 'cubic-bezier(.45,0,.25,1)' });\n  }\n\n  // piscadas de vez em quando enquanto a senha está visível\n  function agendaPiscada() {\n    clearTimeout(piscaTimer);\n    if (REDUZIR) return;\n    piscaTimer = setTimeout(function () {\n      if (senha.type !== 'text') return;\n      vai(.05, 90, sai).then(function () { return vai(1, 180, sai); }).then(agendaPiscada);\n    }, 2800 + Math.random() * 3200);\n  }\n\n  desenha(0);\n  // usado pela animação de entrada: abre um pouquinho e fecha\n  window.trilhaOlho = {\n    espiar: function () {\n      if (senha.type !== 'password') return;\n      vai(.45, 260, sai).then(function () { return new Promise(function (ok) { setTimeout(ok, 380); }); })\n        .then(function () { if (senha.type === 'password') vai(0, 220, sai); });\n    }\n  };\n  mostrar.addEventListener('click', function () {\n    var ver = senha.type === 'password';\n    senha.type = ver ? 'text' : 'password';\n    mostrar.setAttribute('aria-pressed', ver);\n    mostrar.setAttribute('aria-label', ver ? 'Ocultar senha' : 'Mostrar senha');\n    mostrar.title = ver ? 'Ocultar senha' : 'Mostrar senha';\n    senha.classList.remove('revela'); void senha.offsetWidth; senha.classList.add('revela');\n    if (ver) {\n      vai(1, 460, mola).then(function () { if (senha.type === 'text') { olhadinha(); agendaPiscada(); } });\n    } else {\n      clearTimeout(piscaTimer);\n      vai(0, 260, function (p) { return p * p * (3 - 2 * p); });\n    }\n  });\n})();","noAr":true,"ordem":1,"pagina":"myrunning/entrar.html","secao":"Login","secaoOrdem":2,"sistema":"myrunn.ing","tags":["senha","piscar"],"titulo":"Olho que abre e fecha na senha"}$animasys$::jsonb)
  on conflict (id) do update set dados = excluded.dados;
